    'api.sysctl.above_max' => ':label: above :max.',
    'api.sysctl.adv_auto_limiter' => 'The automatic inbound limiter is on. It tightens when the machine\'s load rises — and processing packets you previously dropped raises exactly that load, so it would read this change as distress and ratchet the tracker\'s own budget down. Turn it off before arming anything here.',
    'api.sysctl.adv_conflicts' => 'These keys are also set in: :files. A file sorting after the panel\'s own wins at the next boot, so a change can look permanent for weeks and then evaporate at a reboot nobody connects to it.',
    'api.sysctl.adv_machine' => 'This machine has :ram of memory and :cpus cores; the page size is :page bytes, which is what udp_mem is counted in. Every limit below is checked against those numbers rather than against a recommended value from somewhere else.',
    'api.sysctl.adv_netns' => 'This process is in a private network namespace, so writing any of these would change a copy of the network stack that nothing else on the machine can see. The panel refuses to arm from here rather than report a change that did not happen.',
    'api.sysctl.adv_no_systemd_run' => 'systemd-run is not available, so an armed change could only be undone by the janitor timer. If that timer is not running, nothing will put the old values back for you.',
    'api.sysctl.adv_one_core' => 'ALL inbound packets are being processed by one core: CPU :busiest has handled :pct% of everything this machine has received, across :cpus cores. That is a single-queue NIC delivering every interrupt to the same core, and :rps It explains a symptom none of the buffers can: the tracker looks idle, the per-CPU queue never overflows, and yet raising the inbound limit makes everything else on the box stutter — because everything else is waiting behind that one core.:hint',
    'api.sysctl.adv_rps_hint' => ' Spreading it needs no restart and takes effect immediately. It is system-wide, like the sysctls beside it, so the panel does not write it.',
    'api.sysctl.adv_rps_off' => 'Receive Packet Steering is OFF (rps_cpus is zero on every receive queue).',
    'api.sysctl.adv_rps_on' => 'Receive Packet Steering is on, so this is as spread as it gets here.',
    'api.sysctl.adv_socket_drops' => 'The tracker socket has discarded :n packets because its queue was full. That is the one loss on this page that the buffers below can actually fix — a packet dropped there cost the machine everything except the answer.',
    'api.sysctl.adv_softnet_over' => 'The per-CPU packet queue has overflowed :n times. This is the only measurement that justifies raising it — and remember the value is per CPU, so on :cpus cores it multiplies.',
    'api.sysctl.adv_softnet_zero' => 'The per-CPU packet queue has never overflowed on this machine (softnet dropped = 0 across all :cpus cores), so there is nothing to gain from lengthening it — and it is the change most likely to make an SSH session stutter, because every packet then waits behind a longer queue. Leave it alone.',
    'api.sysctl.adv_spread_ok' => 'Receive processing is spread across :cpus cores (the busiest has :pct% of the packets), so no single core is the bottleneck.',
    'api.sysctl.adv_udp_mem_fine' => 'All UDP sockets on this machine together are using :used pages (:used_bytes) against a pressure threshold of :pressure pages (:pressure_bytes). Nothing is anywhere near it, so raising udp_mem would change nothing — the values circulated in tuning guides are usually a larger fraction of RAM than the machine has.',
    'api.sysctl.adv_udp_mem_near' => 'UDP memory is within reach of the pressure threshold (:used of :pressure pages). This is the measurement that justifies raising udp_mem.',
    'api.sysctl.arm_queued' => 'Queued. The janitor applies it within a minute, and schedules an automatic undo :minutes minute(s) later unless you confirm. Nothing is written to /etc until you do, so until then a reboot also undoes it.',
    'api.sysctl.auto_limiter_on' => 'The automatic inbound limiter is on. It tightens when the machine\'s load rises, and handling packets you were previously dropping raises exactly that — it would read this change as distress and cut the tracker\'s own budget. Turn it off in Settings first.',
    'api.sysctl.backlog_too_high' => 'The queue length is per CPU: :max on :cpus cores is already :total packets buffered ahead of the firewall. Anything larger is refused.',
    'api.sysctl.below_min' => ':label: below :min.',
    'api.sysctl.big_step' => ':label is going up more than fourfold in one step (:cur to :new). Move one thing, watch it, then move the next — a machine that chokes after several of these changed at once tells you nothing about which.',
    'api.sysctl.confirm_queued' => 'Queued. The janitor writes /etc/sysctl.d/99-tracker-panel.conf within a minute and cancels the scheduled undo.',
    'api.sysctl.eighth_of_ram' => ':label: more than an eighth of this machine\'s RAM in one socket buffer — did you mean KiB?',
    'api.sysctl.helper_no_answer' => 'The helper did not answer.',
    'api.sysctl.key_netdev_max_backlog_label' => 'Packets queued before the kernel starts dropping',
    'api.sysctl.key_netdev_max_backlog_what' => 'PER CPU. Lengthening this under a flood does not save the packets — the firewall drops them a few milliseconds later anyway — it just makes every other packet on the machine wait behind them. This is the knob that makes an interactive SSH session stutter.',
    'api.sysctl.key_rmem_default_label' => 'Receive buffer given to every socket',
    'api.sysctl.key_rmem_default_what' => 'What a socket gets without asking. This is the one that costs: it applies to every socket created afterwards that does not set its own size. TCP is not affected — it has its own net.ipv4.tcp_rmem — so in practice this is UDP.',
    'api.sysctl.key_rmem_max_label' => 'Receive buffer ceiling',
    'api.sysctl.key_rmem_max_what' => 'The most a socket may be given, IF it asks. Raising this allocates nothing by itself — only a program that calls setsockopt(SO_RCVBUF) ever sees the difference.',
    'api.sysctl.key_udp_mem_label' => 'Total memory UDP may use (min / pressure / max)',
    'api.sysctl.key_udp_mem_what' => 'A machine-wide ceiling for ALL UDP sockets together, counted in pages. Below "min" the kernel never reclaims, so min is memory promised away rather than a limit; above "max" it refuses. Under a flood the kernel really will take what max allows, and the database is on the same machine.',
    'api.sysctl.key_udp_rmem_min_label' => 'Receive floor guaranteed to each UDP socket',
    'api.sysctl.key_udp_rmem_min_what' => 'How much a UDP socket keeps even when the total above is under pressure. Small and cheap; raising it protects the tracker from being squeezed when something else on the box floods UDP.',
    'api.sysctl.key_udp_wmem_min_label' => 'Send floor guaranteed to each UDP socket',
    'api.sysctl.key_udp_wmem_min_what' => 'The same on the way out.',
    'api.sysctl.key_wmem_default_label' => 'Send buffer given to every socket',
    'api.sysctl.key_wmem_default_what' => 'Same blast radius as the receive default, and the same absence of evidence. If you are here to stop announces being dropped, this is not the knob.',
    'api.sysctl.key_wmem_max_label' => 'Send buffer ceiling',
    'api.sysctl.key_wmem_max_what' => 'The same as the receive ceiling, on the way out. Nothing measured here has ever pointed at the send side; it is offered for symmetry, not as a claim.',
    'api.sysctl.need_ack' => 'Raising :sysctl changes the buffer given to every socket created afterwards, not just the tracker\'s. Tick the acknowledgement to confirm you meant that one.',
    'api.sysctl.no_systemd_run' => 'systemd-run is not available on this machine, so an automatic undo can only come from the janitor timer. If that timer is not running, nothing will put the old values back for you. Confirm you accept that.',
    'api.sysctl.no_values' => 'No values to apply.',
    'api.sysctl.not_all_landed' => 'Not every value actually took effect when this was armed, so making it permanent would write down something that is not true. Revert and look at the per-key result first.',
    'api.sysctl.not_enabled' => 'The kernel-buffer helper is not configured or not enabled (Settings → Kernel network buffers).',
    'api.sysctl.not_integer' => ':label: must be a whole number.',
    'api.sysctl.nothing_armed' => 'Nothing is armed.',
    'api.sysctl.preview_failed' => 'preview failed',
    'api.sysctl.private_netns' => 'This panel is running in a private network namespace, so the change would apply to a copy of the network stack nothing else can see. Refusing rather than reporting a success that means nothing.',
    'api.sysctl.revert_queued' => 'Queued. The janitor puts the captured values back within a minute — and if an automatic revert was scheduled at arm time, systemd may get there first.',
    'api.sysctl.run_bad_command' => 'The helper command contains characters that are not allowed.',
    'api.sysctl.run_exec_disabled' => 'PHP exec() is disabled on this server — the panel cannot reach the helper.',
    'api.sysctl.run_exit_code' => 'Helper exited with code :code',
    'api.sysctl.run_no_helper' => 'No kernel-buffer helper is configured (Settings → Kernel network buffers).',
    'api.sysctl.run_no_json' => 'The helper did not answer with JSON: :out',
    'api.sysctl.run_no_output' => 'The helper produced no output (exit :code). Check the sudoers rule.',
    'api.sysctl.udp_mem_digits' => 'udp_mem values must be whole page counts.',
    'api.sysctl.udp_mem_increasing' => 'udp_mem must be strictly increasing: min < pressure < max.',
    'api.sysctl.udp_mem_max_high' => 'udp_mem max is too high for this machine (:pages pages, :bytes against :ram of RAM). Under a flood the kernel really will take it, and the database is on this same machine.',
    'api.sysctl.udp_mem_min_high' => 'udp_mem min is too high for this machine (:pages pages, :bytes). Below min the kernel never reclaims UDP memory, so that is memory promised away permanently rather than a ceiling — the most this panel will accept here is :cap pages.',
    'api.sysctl.udp_mem_pressure_high' => 'udp_mem pressure is too high for this machine (max :cap pages).',
    'api.sysctl.udp_mem_three' => 'udp_mem needs exactly three numbers: min, pressure and max.',
    'api.sysctl.unknown_error' => 'unknown error',
    'api.sysctl.verdict_clamped' => 'This tracker does ask for a bigger receive buffer and is being clamped by the ceiling (its socket is at :rb, exactly twice net.core.rmem_max — the kernel doubles what a program requests). Raising the ceiling is the cheap fix here: it allocates nothing by itself and touches no other socket.',
    'api.sysctl.verdict_fine' => 'This tracker asks for its own receive buffer size (:rb) and is not being clamped by the ceiling.',
    'api.sysctl.verdict_no_ask' => 'This tracker never asks the kernel for a bigger receive buffer: its socket is sitting at exactly the system default (:rb), not at twice the ceiling, which is where it would be if it had asked. So raising the ceiling alone will change nothing at all here — the only knob that moves this socket is the default, and that one applies to every socket on the machine.',
    'api.sysctl.verdict_stale' => 'This socket is SMALLER than the current default (:rb against :def), and no socket created now could be. A receive buffer is fixed when the socket is opened, so the tracker is still using the value that was in force when it last started — your change is live in the kernel and has not reached this socket. RESTART THE TRACKER and this socket becomes :def; until then the discarded-packet counter will keep climbing for the old reason.',
    'api.sysctl.why_rmem_default' => 'this tracker never asks, so the default is the only knob that reaches its socket',
    'api.sysctl.why_rmem_max' => 'so nothing clamps a program that does ask, now or after an upgrade',
    'api.sysctl.why_udp_rmem_min' => 'a floor each UDP socket keeps when the machine is under memory pressure',
    'api.timeline.custom_needs_span' => 'A custom range needs a span in seconds.',
    'api.timeline.disabled' => 'Statistics timeline is disabled',
    'api.timeline.not_public' => 'Statistics timeline is not public',
    'api.timeline.query_failed' => 'Timeline query failed',
    'api.timeline.too_many' => 'Too many requests',
    'api.timeline.unknown_range' => 'Unknown range. Use 24h, 7d, 14d, 30d, 60d, 90d, all or custom+span.',
    'api.transparency.disabled' => 'Transparency page is disabled',
    'api.tuner.already_running' => 'A run is already going.',
    'api.tuner.both_limits' => 'That run moved the receive limit and the reply budget together, so there is no single value to apply. Set them from their own cards.',
    'api.tuner.cancel_requested' => 'Asked the run to stop. It restores on its way out; if it cannot, the janitor puts the settings back within a minute.',
    'api.tuner.disabled' => 'The stability probe is switched off in Settings.',
    'api.tuner.helper_refused' => 'The helper refused it.',
    'api.tuner.inbound_set' => 'Inbound limit set to :pps pps.',
    'api.tuner.inconclusive' => 'That run could not tell its steps apart, so none of its values were measured. Run the probe again before applying anything.',
    'api.tuner.not_a_step' => 'That limit was not one of the steps this run measured.',
    'api.tuner.reply_budget_set' => 'Reply budget set to :pps packets/second.',
    'api.tuner.requested' => 'Requested. The janitor starts it within a minute; the settings are recorded first, so they go back even if the run is interrupted.',
    'api.tuner.unusable_limit' => 'That is not a usable limit.',
    'api.twofa.already_on' => 'Two-factor authentication is already on. Turn it off first if you want a new secret — that way the old one stops working the moment the new one starts.',
    'api.twofa.begin_note' => 'Nothing is switched on yet. Add the key to your authenticator app, then enter a code from it below — that is what proves the key arrived intact, and only then does anything change.',
    'api.twofa.code_required' => 'A current code (or a recovery code) is required as well as the password. Two-factor authentication is for the case where somebody else has the password, so the password alone cannot switch it off.',
    'api.twofa.config_not_writable' => 'config/ is not writable, so the secret could not be stored. Fix that before starting: a setup that cannot be saved would leave you with an app generating codes for a secret this server has forgotten.',
