    'home.about_head' => 'About the Tracker',
    'home.about_open' => 'This is a free, public BitTorrent tracker running erdgeist OpenTracker software. It has been running on Linux Debian since 2020 and supports both IPv4 and IPv6.',
    'home.about_sched' => 'This is a free BitTorrent tracker running erdgeist OpenTracker software in <strong>scheduled whitelist mode</strong>: during whitelist hours (:hours) it serves <strong>registered torrents only</strong>; outside those hours it runs as an open tracker. Right now it is in <strong>:mode mode</strong>. Registration is free and anonymous:reg. It has been running on Linux Debian since 2020 and supports both IPv4 and IPv6.',
    'home.about_wl' => 'This is a free BitTorrent tracker running erdgeist OpenTracker software in <strong>whitelist mode</strong>: it serves <strong>registered torrents only</strong>. Registration is free and anonymous:reg. It has been running on Linux Debian since 2020 and supports both IPv4 and IPv6.',
    'home.announce_copy' => 'Copy announce URLs',
    'home.announce_extra' => 'This tracker runs on more than one port. Add <strong>all</strong> of them to your client — each is answered by a different process, and using only the first leaves the others idle.',
    'home.announce_head' => 'Announce URL',
    'home.contact_cta' => 'If you wish to report infringing content, please use our <a href=":url" class="report-link">[ Submit a Report ]</a>',
    'home.contact_head' => 'Contact',
    'home.contact_note_a' => 'Reports submitted through the form above are reviewed faster and receive status updates. For business inquiries, partnership requests, or if you have not received a response to your report, you may contact us via ',
    'home.contact_reveal' => '[click to reveal contact]',
