    'home.tagline' => 'Public BitTorrent tracker powered by OpenTracker',
    'info.a_accounts' => 'An account is optional — the tracker works without one. It unlocks member features according to the groups it holds, such as searching the index or registering torrents without a CAPTCHA. What is stored for an account is listed in the Terms.',
    'info.a_data' => 'The tracker only stores active swarms — a list of info_hashes and their associated peers (IP + port). This data is temporary and removed when a peer\'s session expires. No files, torrent names, or content are stored.',
    'info.a_data_index' => 'The index additionally keeps, per observed hash, the torrent name and file list fetched from the swarm — metadata, not content.',
    'info.a_how' => 'A BitTorrent client sends an "announce" request to the tracker with the torrent\'s info_hash. The tracker responds with a list of peers currently sharing or downloading the same torrent. The tracker only knows: the info_hash, the peer\'s IP address, and port.',
    'info.a_index' => 'Besides serving swarms, this tracker keeps an index of the info hashes it has seen, and fetches each torrent\'s name and file list from the swarm itself. It exists so that an abuse report naming a title can be matched to a hash, and so that a hash can be shown for what it is. Nothing is downloaded beyond the metadata; entries expire once a swarm has been quiet for a while.',
    'info.a_index_search' => 'Members can <a href=":url">search it</a>.',
    'info.a_ot' => 'OpenTracker is a high-performance BitTorrent tracker software created by erdgeist. It is open-source, extremely fast, and minimalist. It can handle millions of connections with minimal resource usage.',
    'info.a_what' => 'A BitTorrent tracker is a server that helps BitTorrent clients communicate. It coordinates file transfers between users (peers) by tracking who is sharing a given torrent. The tracker does not store any files — only information about active swarm participants.',
    'info.a_wl' => 'This tracker runs OpenTracker in <strong>whitelist mode</strong>: announces are only answered for info hashes that were <strong>registered</strong> beforehand. Torrents posted on our community forum are registered automatically; anyone else can register a magnet link or info hash for free on the <a href=":url">Whitelist page</a> (CAPTCHA + rate limits apply, the registrant\'s IP is stored to fight abuse). Registered hashes may be removed or banned after an abuse report. Unregistered hashes receive an empty / "not authorized" answer.',
    'info.faq_a1_open' => 'The tracker automatically removes swarms when all peers\' sessions expire. We do not control which torrents are tracked.',
    'info.faq_a1_wl' => 'Yes — in whitelist mode a hash can be removed from (or banned on) the whitelist, after which the tracker stops answering announces for it. Use the report form.',
    'info.faq_a2' => 'No. An info_hash is merely a SHA1 digest of the torrent\'s metadata. The tracker has no information about file contents.',
    'info.faq_a3' => 'No. We do not keep persistent connection logs. Random IP addresses are inserted into peer lists to protect privacy.',
    'info.faq_a4' => 'Since the tracker does not store any files or content, copyright holders should contact the indexing site (e.g., the torrent site), not the tracker. You may, however, submit a report using our form.',
    'info.faq_a5' => 'No. The tracker does not store .torrent files. It only tracks active peer connections.',
    'info.faq_a6' => 'Yes — the switcher in the navigation changes the language for this browser session, and a signed-in account can save a preferred language on its account page.',
    'info.faq_head' => 'Frequently Asked Questions',
    'info.faq_q1' => 'Can you remove an info_hash?',
    'info.faq_q2' => 'Can you see what content is behind a hash?',
    'info.faq_q3' => 'Do you keep IP address logs?',
    'info.faq_q4' => 'What should copyright holders do?',
    'info.faq_q5' => 'Do you have .torrent files?',
    'info.faq_q6' => 'Can I read this site in another language?',
