    'settings.account_email' => 'Admin Email',
    'settings.account_email_cancel_change' => 'Cancel change',
    'settings.account_email_change_to' => 'Email change to',
    'settings.account_email_cooldown' => 'The next change is possible :days days after the previous one.',
    'settings.account_email_hint1' => 'The address of <strong>your own account</strong> (:username) — account notices, the verification link and site password resets go here.',
    'settings.account_email_hint2' => 'This is <em>not</em> the public contact address (Site Email) nor the sender (From) — both live under Contact &amp; Email.',
    'settings.account_email_hint3' => 'Editing it starts the same two-step change a member gets: confirm from the <strong>current</strong> mailbox first, then from the new one; clear the box to remove the address.',
    'settings.account_email_no_account' => 'This panel login has no account row in <code>users</code>, so there is no address to manage. Create a user with the same username on the Users page to link one.',
