    'settings.account_save' => 'Save Credentials',
    'settings.account_title' => 'Security & Credentials',
    'settings.account_username' => 'Admin Username',
    'settings.account_username_hint' => 'Current password is required to change username.',
    'settings.admin_access_client_ip_header' => 'Client IP header',
    'settings.admin_access_client_ip_header_hint' => 'Needed for correct per-IP rate limiting behind Cloudflare / a reverse proxy.',
    'settings.admin_access_client_ip_header_note' => '(leave empty to use the raw connection IP)',
    'settings.admin_access_client_ip_header_ph' => 'e.g. CF-Connecting-IP or X-Forwarded-For',
    'settings.admin_access_hidden_404' => 'Answer 404 Not Found',
    'settings.admin_access_hidden_behavior' => 'Other admin URLs when signed out',
    'settings.admin_access_hidden_behavior_hint' => 'What a visitor who is not signed in gets on a panel URL other than the sign-in address above. The default shows no login form anywhere except at your own address (the API still answers <code>401</code> to admin calls, so this hides the panel from browsing, not from a determined scan).',
    'settings.admin_access_hidden_home' => 'Redirect to the front page (default)',
    'settings.admin_access_hidden_login' => 'Show the sign-in form (classic)',
    'settings.admin_access_lockout_attempts' => 'Login lockout attempts',
    'settings.admin_access_lockout_minutes' => 'Login lockout window (min)',
    'settings.admin_access_login_path' => 'Admin sign-in address',
    'settings.admin_access_login_path_hint' => 'The only address that shows this sign-in form. Moving it somewhere unguessable (e.g. <code>admin123yzxadminxxx</code>) keeps crawlers and drive-by bots off the form — it is <em>not</em> a substitute for a strong password: the login API lives at a fixed address and the real brute-force protection is the lockout below (plus <em>On Admin Login</em> in the CAPTCHA section). While a custom address is set, that API additionally refuses any sign-in from a session that never opened this page. Letters, digits, <code>-</code> and <code>_</code>; empty, or a name already used by another page, falls back to <code>admin</code>. The panel pages keep their normal addresses (<code>?action=admin</code>, <code>?action=settings</code>, …) once you are signed in, so bookmarks, links and the Logout button keep working. <strong>Write the new address down before saving.</strong>',
    'settings.admin_access_reauth_max_attempts' => 'Wrong password confirmations before sign-out',
    'settings.admin_access_reauth_max_attempts_hint' => 'Every dangerous action asks for the password again. This many wrong answers <strong>signs the session out</strong> — getting back in means the sign-in page, with its CAPTCHA and address lockout. Each wrong answer also costs progressively more time, starting at once. The session gate keeps strangers out; this is for whoever is already sitting at the machine.',
    'settings.admin_access_session_absolute' => 'Session absolute cap (hours)',
    'settings.admin_access_session_absolute_hint' => 'Hard limit since login regardless of activity.',
    'settings.admin_access_session_idle' => 'Session idle timeout (min)',
    'settings.admin_access_session_idle_hint' => 'Logs the admin out after this long with no activity.',
    'settings.admin_access_title' => 'Admin Access & Sessions',
    'settings.admin_access_trusted_proxy_ips' => 'Trusted proxy IPs',
    'settings.admin_access_trusted_proxy_ips_hint' => 'Only when the request comes from one of these is the forwarded-IP header trusted.',
    'settings.admin_access_trusted_proxy_ips_note' => '(comma separated, leave empty if no proxy)',
    'settings.admin_access_trusted_proxy_ips_ph' => 'e.g. 173.245.48.1, 103.21.244.0',
    'settings.api_ban_days' => 'Ban length (days)',
    'settings.api_budgets_intro' => 'The ban machinery above only reacts to <em>bad</em> authentication. These two budgets are what limits a key that is perfectly valid — a federation peer pulling pages, or a key that has leaked. They are counted <strong>per key</strong> (not per IP, so one partner cannot be starved by a stranger behind the same NAT), and going over answers <code>429</code> with <code>Retry-After</code> rather than a ban: pulling too fast is a misconfiguration between partners, not an attack. Addresses in <em>Never-ban IPs</em> are exempt from these too. <strong>0 switches a budget off.</strong>',
    'settings.api_bytes_day' => 'Bytes per day',
    'settings.api_bytes_day_hint' => '0 = unlimited. Counts what we <em>send</em> as well as what we receive, so a runaway export is caught. Stored in bytes; the unit here is only how it is shown to you.',
    'settings.api_exempt_ips' => 'Never-ban IPs',
    'settings.api_exempt_ips_hint' => '(comma-separated IPs or CIDRs; keep this server\'s own addresses here — the forum on the same host must never lock itself out)',
    'settings.api_intro' => '<code>POST v1/whitelist/submit</code> / <code>GET v1/whitelist/ping</code> with <code>Authorization: Bearer key_id.secret</code> (used by the forum extension). <strong>Every failed authentication that carries an Authorization header bans the source IP</strong> (IPv4 exactly, IPv6 per /64) for the number of days below and stores the offending request. Requests without a header get 401 without a ban.',
    'settings.api_label' => 'API',
    'settings.api_managed_on' => 'Clients (keys) and bans are managed on the',
    'settings.api_per_key' => '(per key)',
    'settings.api_rpm' => 'Requests per minute',
    'settings.api_rpm_hint' => '0 = unlimited. A federation pull is one request per page, so 60 is generous.',
    'settings.api_size_aria' => 'Size',
    'settings.api_title' => 'Server-to-server API',
    'settings.api_unit_aria' => 'Unit',
    'settings.api_unit_bytes' => 'bytes',
    'settings.api_whitelist_page' => 'Whitelist page',
    'settings.audit_intro' => 'Who did what in the panel. The log is read-only from here on purpose — a record the panel it describes can edit is not a record. Credentials are never written to it: a setting that holds one appears as “changed”, never as its value.',
    'settings.audit_keep_days' => 'Keep for (days)',
    'settings.audit_keep_days_hint' => 'The janitor removes anything older, a few thousand rows per run.',
    'settings.audit_opt_no_record' => 'Do not record',
    'settings.audit_opt_record' => 'Record panel actions',
    'settings.audit_recording' => 'Recording',
    'settings.audit_recording_hint' => 'Turning this off stops new entries; it does not remove the ones already written.',
    'settings.audit_title' => 'Audit log',
    'settings.backups_auto_label' => 'Automatic backup',
    'settings.backups_cmd_hint' => 'Only letters, digits, space and <code>_ . / -</code> — no shell metacharacters.',
    'settings.backups_cmd_label' => 'Root helper command',
    'settings.backups_cmd_label_sub' => '(the action arguments are appended automatically)',
    'settings.backups_cmd_ph' => 'e.g. :cmd',
    'settings.backups_custom_hint' => 'These are <code>Backup-serwera.sh</code> item names. Other services on this machine (mail, forum, files) have their own items — add them by hand in the field the toolkit\'s <code>--list</code> shows if you want one archive for everything.',
    'settings.backups_custom_label' => 'Custom selection',
    'settings.backups_custom_label_sub' => '(used by the "Custom selection" profile)',
    'settings.backups_db_hint' => 'Letters, digits and <code>_</code>. This is also the name you have to type to confirm a restore.',
    'settings.backups_db_label' => 'Database to dump / restore',
    'settings.backups_dir_hint' => 'An archive contains every database password on this box, so a path the web server could serve is refused outright.',
    'settings.backups_dir_label' => 'Directory',
    'settings.backups_dir_label_sub' => '(outside the web root; created <code>0700 root</code> on the first run)',
    'settings.backups_dir_test_btn' => 'Test',
    'settings.backups_enabled_hint' => 'Off means nothing runs on a timer. You can still make a backup by hand from the Backups page.',
    'settings.backups_gpg_hint' => '<strong>Public-key</strong> encryption (<code>gpg --encrypt --recipient</code>), because it needs no passphrase and therefore no terminal. Import the key as root first (<code>gpg --import</code>). Leave empty and the archives sit on disk in the clear — acceptable while they never leave a server only root can read, and not acceptable the moment you copy one off it.',
    'settings.backups_gpg_label' => 'Encrypt for',
    'settings.backups_gpg_label_sub' => '(GPG key id or email; empty = no encryption)',
    'settings.backups_heading' => 'Backups',
    'settings.backups_intro' => 'This backs up <strong>the tracker</strong>. Backing up the whole machine — mail, the forum, certificates — is a separate job for the server toolkit, and the panel does not try to be it. By default it dumps the tracker database with <code>mariadb-dump</code>. If <code>Backup-serwera.sh</code> is installed here, the panel drives <em>that</em> instead, through the root helper <code>tools/opentracker/tracker-backup.sh</code> — so there is one backup program on this machine, not two — and the profiles below gain its configuration, list, unit and firewall items. Browse, verify, download and restore archives on the',
    'settings.backups_intro_after' => '; this section is the policy.<br>Nothing heavy ever runs in a web request: a backup is started detached and reports back through a state file the page polls.',
    'settings.backups_intro_link' => 'Backups page',
    'settings.backups_keep_days_label' => 'Delete older than',
    'settings.backups_keep_days_label_sub' => '(days; 0 = no limit)',
    'settings.backups_keep_heading' => 'How long they stay',
    'settings.backups_keep_label' => 'Keep at most',
    'settings.backups_keep_label_sub' => '(archives; 0 = no limit)',
    'settings.backups_label' => 'Backups',
    'settings.backups_max_gb_hint' => 'Oldest first, until the directory fits. The last archive standing is never deleted — a full disk is bad, no backup at all is worse.',
    'settings.backups_max_gb_label' => 'Directory ceiling',
    'settings.backups_max_gb_label_sub' => '(GB; 0 = no limit)',
    'settings.backups_nice_hint' => '15 keeps a dump from fighting the tracker for CPU and disk; the helper also asks systemd for idle I/O.',
    'settings.backups_nice_label' => 'Process priority',
    'settings.backups_nice_label_sub' => '(nice, 0–19)',
    'settings.backups_off' => 'Disabled',
    'settings.backups_on' => 'On — allow the schedule to run',
    'settings.backups_profile_hint' => '<strong>Light</strong> leaves out <code>index_hashes</code> / <code>index_files</code> — on this install those are the two biggest tables by far and they rebuild themselves from the swarm. <strong>Full</strong> takes everything.',
    'settings.backups_profile_label' => 'Profile',
    'settings.backups_sched_at' => 'at',
    'settings.backups_sched_hint' => 'Tick no days and nothing runs automatically. The janitor timer fires it (never a web request), and a slot that was missed because the machine was off still runs later the same day — but never twice for the same slot.',
    'settings.backups_script_hint' => 'Not found? The panel falls back to dumping the tracker database only, and the Backups page says so.',
    'settings.backups_script_label' => 'Path to <code>Backup-serwera.sh</code>',
    'settings.backups_script_label_sub' => '(empty = look in the usual places)',
    'settings.backups_tools_heading' => 'Tools',
    'settings.backups_tz_label' => 'Timezone',
    'settings.backups_verify_hint' => 'An archive nobody has ever read back is a guess, not a backup.',
    'settings.backups_verify_label' => 'Check each archive after writing it',
    'settings.backups_verify_no' => 'No',
    'settings.backups_verify_yes' => 'Yes — checksum + read it back',
    'settings.backups_what_heading' => 'What goes in',
    'settings.backups_when_heading' => 'When',
    'settings.bulk_mail_hint_a' => 'Adds <strong>Write to members</strong> on the',
    'settings.bulk_mail_hint_b' => 'a message to a selection, a group, or everyone. In-app notifications work with this off — this switch is about <em>email</em>. Off by default.',
    'settings.bulk_mail_label' => 'Write to everyone (bulk mail)',
    'settings.bulk_mail_per_minute' => 'Bulk mail per minute',
    'settings.bulk_mail_per_minute_hint' => 'This server sends through <code>mail()</code> with no relay in front of it, so a hundred messages leaving at once from a domain that normally sends a handful is what gets it filed under bulk — and the first casualty is the password-reset mail. The panel only queues; the janitor sends this many a minute.',
    'settings.bulk_mail_retries' => 'Bulk mail retries',
    'settings.bulk_mail_retries_hint' => 'Tries per message before it is marked failed, backing off longer each time. A mailer that is refusing does not want to be asked again immediately.',
    'settings.captcha_enable' => 'Enable CAPTCHA',
    'settings.captcha_hcaptcha_secret' => 'hCaptcha Secret Key',
    'settings.captcha_hcaptcha_site_key' => 'hCaptcha Site Key',
    'settings.captcha_heading' => 'CAPTCHA',
    'settings.captcha_intro' => 'Pick a provider and fill its keys. The switches below decide where a CAPTCHA is asked; the public whitelist registration page always requires one (it is disabled when CAPTCHA is not configured).',
    'settings.captcha_on_appeal' => 'On Appeal Forms',
    'settings.captcha_on_block_check' => 'On Block Check',
    'settings.captcha_on_login' => 'On Admin Login',
    'settings.captcha_on_report' => 'On Report Form',
    'settings.captcha_on_status' => 'On Status Check',
    'settings.captcha_provider' => 'Provider',
    'settings.captcha_provider_hcaptcha' => 'hCaptcha (checkbox)',
    'settings.captcha_provider_recaptcha' => 'Google reCAPTCHA v2 (checkbox)',
