    'settings.captcha_smart_heading' => 'Smart CAPTCHA',
    'settings.captcha_smart_intro' => 'CAPTCHA only appears after a user accumulates enough activity points. Solving it grants a grace period where no CAPTCHA is required. Failed admin logins always reset the grace period.',
    'settings.captcha_smart_lockout_attempts' => 'Failed attempts before Lockout',
