    'settings.cluster_cmd' => 'Helper command',
    'settings.cluster_cmd_hint' => 'Empty = the feature does not exist: no card, no polling, no <code>sudo</code>.',
    'settings.cluster_cmd_ph' => 'e.g. sudo -n /usr/local/sbin/tracker-cluster.sh',
    'settings.cluster_intro_a' => 'Run <strong>more than one</strong> opentracker on this machine, on extra UDP ports, when one has genuinely run out of CPU. Check the',
    'settings.cluster_intro_b' => 'first: it says outright whether this would help, and on most machines it will not — the cheap knobs (worker count, priority, socket buffers) are worth nearly all of the available gain at nearly none of the risk. The installer’s own <code>opentracker.service</code> is <strong>never touched</strong>; extras are added beside it, share the same accesslist and the same white/black mode, and removing them removes every trace. Off by default.',
    'settings.cluster_perf_card_link' => 'performance card',
    'settings.cluster_title' => 'OpenTracker instances',
    'settings.confirm_body' => 'You are modifying report deletion security limits. Enter your admin password to confirm and apply these changes.',
    'settings.confirm_body_exec' => 'You are changing a setting that decides what the server executes or whom it trusts. Enter your admin password to confirm and apply these changes.',
    'settings.confirm_cancel' => 'Cancel',
    'settings.confirm_password' => 'Admin Password *',
    'settings.confirm_submit' => 'Confirm Changes',
    'settings.confirm_title' => 'Confirm Settings Changes',
    'settings.content_allow_bbcode' => 'Allow BBCode',
    'settings.content_allow_markdown' => 'Allow Markdown',
    'settings.content_allow_markdown_hint' => 'With both on, whoever writes picks. With both off, BBCode is still offered — a description field with no syntax at all would be a trap.',
    'settings.content_autopublish' => 'Always publish',
    'settings.content_autopublish_hint' => 'Separate from <em>Review before publishing</em> on purpose: “I do not moderate” and “I moderate, but let this one through” are different decisions, and collapsing them into one switch means you cannot make the second.',
    'settings.content_autopublish_yes' => 'Yes — skip the queue entirely',
    'settings.content_description' => 'Description field',
    'settings.content_disabled' => 'Disabled',
    'settings.content_edit_max_pending' => 'Rewrite proposals per torrent',
    'settings.content_edit_max_pending_hint' => 'Registering a hash that already exists, with a description, <strong>proposes a rewrite</strong> rather than changing anything — anyone can register somebody else&rsquo;s torrent, so the first description is not automatically the right one. Proposals appear under <strong>Whitelist &rarr; To review &rarr; Rewrites</strong>, old and new side by side. 0 = do not accept proposals.',
    'settings.content_enabled' => 'Enabled',
    'settings.content_intro' => 'Two optional fields on the registration form: <strong>where the torrent came from</strong>, and <strong>what it is</strong>. They appear on the public whitelist, the Index and the public search. Both are <strong>off by default</strong>, because this is text an anonymous stranger types and you then publish under your own domain — a description can carry images and a link goes wherever its author decided. With review on (the default when you switch these on), the torrent still registers <em>immediately</em>; only the link and the description wait for you.',
    'settings.content_max_chars' => 'Max characters',
    'settings.content_max_images' => 'Max images',
    'settings.content_max_images_hint' => '0 = none. Every image is a request from your visitor to somebody else\'s server.',
    'settings.content_max_links' => 'Max links',
    'settings.content_no' => 'No',
    'settings.content_review' => 'Review before publishing',
    'settings.content_review_hint_link' => 'Whitelist page',
    'settings.content_review_hint_post' => 'Turning this off means the first bad description is public before anyone has seen it.',
    'settings.content_review_hint_pre' => 'Held items appear under <strong>To review</strong> on the',
    'settings.content_review_no' => 'No — publish at once',
    'settings.content_review_yes' => 'Yes — hold for review',
    'settings.content_sl_refresh' => 'Let visitors refresh S/L',
    'settings.content_sl_refresh_hint' => 'Adds a refresh button to the Info panel in the public search, scraping that one hash live. Off by default: it is a button that makes strangers\' clicks into tracker requests.',
    'settings.content_sl_refresh_seconds' => 'Refresh cooldown (s)',
    'settings.content_sl_refresh_seconds_hint' => 'Per hash, across every visitor. Without this the button is a free load generator pointed at your own tracker.',
    'settings.content_source_url' => 'Source link field',
    'settings.content_source_url_hint' => '<strong>https only.</strong> Plain HTTP is refused rather than upgraded: this page is served over TLS and must not hand anyone a downgrade. Private addresses and credentials in the URL are refused too.',
    'settings.content_subtitle' => 'What submitters may write, and who reviews it',
    'settings.content_title' => 'Descriptions & source links',
    'settings.content_trusted_domains' => 'Domains that need no warning',
    'settings.content_trusted_domains_hint' => 'Every off-site link asks the visitor to confirm first. These domains (and their subdomains) skip that. Empty = warn on everything, including your own.',
    'settings.content_trusted_domains_ph' => 'e.g. tryhackx.org, files.example.org',
    'settings.content_yes' => 'Yes',
    'settings.donation_field_add' => 'Add Field',
    'settings.donation_field_label_ph' => 'Label',
    'settings.donation_field_remove_title' => 'Remove',
    'settings.donation_field_value_ph' => 'Address, hash, or URL',
    'settings.donations_enabled' => 'Show Donations',
    'settings.donations_hint' => 'Add up to 15 custom fields. URLs (http/https) will display as clickable links. Other values (wallet addresses, hashes) will display as copyable code.',
    'settings.donations_no' => 'No',
    'settings.donations_title' => 'Donation Fields',
    'settings.donations_yes' => 'Yes',
    'settings.federation_add_peer' => 'Add peer',
    'settings.federation_enabled' => 'Federation',
    'settings.federation_enabled_off' => 'Disabled',
    'settings.federation_enabled_on' => 'Enabled',
    'settings.federation_exchange_hint' => 'Exchange flow: each admin adds the other as a peer, ticks <em>grant inbound access</em>, and sends the generated bearer to the other side, who pastes it into <em>Their bearer</em> and enables <em>Pull</em>. Test verifies the outbound direction. <em>Undo import</em> returns everything a peer contributed to unresolved — the hashes and their local history stay, only the borrowed descriptions go.',
    'settings.federation_export_enabled' => 'Export to peers',
    'settings.federation_export_files' => 'Export file lists',
    'settings.federation_export_files_no' => 'No (name/size only)',
    'settings.federation_export_max_batch' => 'Rows per export page',
    'settings.federation_export_max_batch_hint' => 'Counts torrents, not what they contain — see the two budgets beside it.',
    'settings.federation_export_max_bytes' => 'Bytes per export page',
    'settings.federation_export_max_bytes_hint' => '0 = no limit, measured on the wire.',
    'settings.federation_export_max_files' => 'File records per export page',
    'settings.federation_export_max_files_hint' => '0 = no limit. A page ends on whichever of the three runs out first, and hands back the cursor — so a heavy catalogue produces smaller pages on its own.',
    'settings.federation_export_no' => 'No (pull only)',
    'settings.federation_grant_label' => 'grant inbound access',
    'settings.federation_grant_title' => 'Also create an API key (scope: federation) the peer uses to pull FROM us — shown once',
    'settings.federation_import_batch_bytes' => 'Import batch (bytes)',
    'settings.federation_import_batch_bytes_hint' => 'Whichever fills first ends the batch. 33554432 = 32 MB.',
    'settings.federation_import_batch_rows' => 'Import batch (rows)',
    'settings.federation_import_batch_rows_hint' => 'Rows the importer holds before it commits. The cursor moves with the batch, so an interrupted run costs at most this many rows — never a repair job.',
    'settings.federation_import_max_seconds' => 'Import time budget (s)',
    'settings.federation_import_max_seconds_hint' => 'One pass. What is left is picked up next time — the cursor makes that free.',
    'settings.federation_import_mode' => 'Trust incoming metadata',
    'settings.federation_import_mode_fill' => 'Straight in (fill)',
    'settings.federation_import_mode_hint' => 'In review mode nothing a peer sends reaches the catalogue until you accept it — it waits in the queue below. Names are rendered as text, never as markup, so this is about <em>what you publish</em>, not about script injection. The first sync of a large peer can park tens of thousands of rows, so accept per peer rather than one at a time.',
    'settings.federation_import_mode_review' => 'Hold for review (quarantine)',
    'settings.federation_import_new' => 'Accept new hashes',
    'settings.federation_import_new_hint' => 'Imported rows count against the Index row cap.',
    'settings.federation_import_new_no' => 'No (only fill my observed hashes)',
    'settings.federation_import_new_yes' => 'Yes (grow the index from peers)',
    'settings.federation_intro' => 'Exchange resolved Index <strong>metadata</strong> with other tracker nodes so everyone builds a bigger search catalogue without re-fetching from the DHT. Pull-based: each node pulls compressed JSON pages from its peers\' <code>v1/federation/export</code> (bearer key with the <em>federation</em> scope) and merges them with <code>worker/federation.py</code> (systemd timer — <strong>not</strong> PHP web time; see <code>worker/README.md</code>). By default an import only <em>fills in metadata</em> for hashes this tracker has itself observed; “accept new hashes” also inserts hashes never seen here. Needs the S2S API enabled above. Peers are managed below.',
    'settings.federation_loading' => 'Loading…',
    'settings.federation_no' => 'No',
    'settings.federation_node_name' => 'Node name',
    'settings.federation_node_name_hint' => 'Shown to peers in export replies.',
    'settings.federation_node_name_ph' => 'my-tracker',
    'settings.federation_peer_bearer' => 'Their bearer',
    'settings.federation_peer_bearer_note' => '(for pulling FROM them; optional)',
    'settings.federation_peer_name_ph' => 'other-tracker',
    'settings.federation_peers' => 'Peers',
    'settings.federation_pull_minutes' => 'Pull interval (min)',
    'settings.federation_pull_minutes_hint' => 'Honoured by <code>federation.py</code> when run in loop mode; a systemd timer uses its own schedule.',
    'settings.federation_review_accept_peer' => 'Accept whole peer…',
    'settings.federation_review_accept_peer_title' => 'Accept everything still waiting from the peer selected on the left',
    'settings.federation_review_accept_sel' => 'Accept selected',
    'settings.federation_review_all_peers' => 'All peers',
    'settings.federation_review_hint' => 'Everything below arrived from a peer while <em>Trust incoming metadata</em> was set to review. Nothing here is in the catalogue or in search. Accepting merges a package exactly as a normal import would; rejecting keeps a note so the peer does not offer it again on every pull.',
    'settings.federation_review_refresh' => 'Refresh',
    'settings.federation_review_reject_sel' => 'Reject selected',
    'settings.federation_review_state_pending' => 'Waiting',
    'settings.federation_review_state_rejected' => 'Rejected',
    'settings.federation_review_th_files' => 'Files',
    'settings.federation_review_th_peer' => 'Peer',
    'settings.federation_review_th_resolved' => 'Resolved',
    'settings.federation_review_th_size' => 'Size',
    'settings.federation_review_title' => 'Waiting for review',
    'settings.federation_size_aria' => 'Size',
    'settings.federation_th_base_url' => 'Base URL',
    'settings.federation_th_imported' => 'Imported',
    'settings.federation_th_inbound_key' => 'Inbound key',
    'settings.federation_th_last_pull' => 'Last pull',
    'settings.federation_th_name' => 'Name',
    'settings.federation_th_pull' => 'Pull',
    'settings.federation_th_status' => 'Status',
    'settings.federation_title' => 'Federation / Cluster',
    'settings.federation_unit_aria' => 'Unit',
    'settings.federation_unit_bytes' => 'bytes',
    'settings.federation_worker_mem_mb' => 'Importer memory ceiling (MB)',
    'settings.federation_worker_mem_mb_hint' => 'A hard <code>RLIMIT_AS</code> on the importer process. Every other guard is a promise about arithmetic; this one is the floor under them — the process dies rather than the machine, and the timer restarts it from the last committed batch.',
    'settings.federation_yes' => 'Yes',
    'settings.fetch_order_building' => 'building',
    'settings.fetch_order_building_title' => 'the index this ordering needs is still being built',
    'settings.fetch_order_intro' => 'Which pending hash the worker takes next, on the <strong>index</strong> queue. On a queue of millions this decides what the tracker knows anything about for months: <em>queue order</em> is fair, and it is also the reason a release added yesterday sits behind a million hashes nobody has seeded since 2019. Applied within ~60&nbsp;s, no restart.',
    'settings.fetch_order_label' => 'Fetch order',
    'settings.fetch_order_live_hint' => 'A mode is a query plan, not a preference. This one runs on',
    'settings.fetch_order_live_label' => 'What the worker is actually doing',
    'settings.fetch_order_mix_hint' => 'The shares always add up to 100: raising one takes the difference from the others in proportion. The mix repeats over <strong>100 claims</strong>, interleaved rather than blocked &mdash; so 70/15/15 is not seventy of one kind followed by fifteen of the next, and any single wave of parallel fetches is already a proportional sample. One point is therefore one fetch in a hundred: small, but never zero. The note under each field says what that works out to at the parallel-fetch setting above, which is the number that decides whether a share is worth having.',
    'settings.fetch_order_mix_reset' => 'Reset to default',
    'settings.fetch_order_mix_title' => 'Mix shares',
    'settings.fetch_order_mix_wl_more' => 'What the whitelist share does',
    'settings.fetch_order_mix_wl_more_body' => '<strong>0 means the whitelist keeps absolute priority</strong> &mdash; it drains completely before any index row, exactly as in every other mode and every earlier release, so leaving it alone changes nothing. Give it a number and it becomes a guaranteed slice of the rotation instead: use that when a bulk import has put fifty thousand rows in front of the index and you want both to move. A slot whose queue turns out to be empty is not wasted &mdash; it falls through to the other queue &mdash; so the share is a floor for the whitelist, never a ceiling on throughput.',
    'settings.fetch_order_still_building' => 'index still building',
    'settings.fetch_order_title' => 'Metadata fetch order',
    'settings.fetch_order_why' => 'Why these orderings and not others',
    'settings.fetch_order_why_1' => 'A claim runs on every fetch slot &mdash; several times a second &mdash; so every mode here has to be a sort an <strong>existing index</strong> can serve; anything else is a filesort over three million rows at that rate. Left out on purpose:',
    'settings.fetch_order_why_2' => 'And <em>Random</em> is not <code>ORDER BY RAND()</code>, which would read and sort the whole table: info hashes are SHA-1 digests and therefore uniform across the key space, so a random point plus &ldquo;the first pending row at or after it&rdquo; is an index seek.',
    'settings.fetch_order_wl_hint' => 'The <strong>whitelist</strong> queue is not affected: outside the mix it always drains first, because those rows are there because somebody asked for them by name.',
    'settings.footer_author' => 'Author',
    'settings.footer_author_url' => 'Author URL',
