    'settings.group_maintenance' => 'Backups',
    'settings.group_network' => 'Network & limits',
    'settings.group_opentracker' => 'OpenTracker service',
    'settings.group_security' => 'Security & CAPTCHA',
    'settings.group_stats' => 'Statistics',
    'settings.group_tracker' => 'Tracker & whitelist',
    'settings.group_users' => 'User accounts',
    'settings.groups_all' => 'All settings',
    'settings.groups_aria' => 'Settings groups',
    'settings.home_arrange' => 'Arrange sections',
    'settings.home_badge_builtin' => 'built-in layout',
    'settings.home_badge_rearranged' => 'rearranged',
    'settings.home_front_page' => 'Front page',
    'settings.home_intro' => 'The front page is built from seven sections. Drag them into the order you want, hide the ones you do not, rename the headings above them — and <strong>write your own text for any of them</strong>, or add sections of your own. A custom text can paste the live pieces in where it says <code>{{block:announce}}</code>, <code>{{torrent_count}}</code>, <code>{{register_button}}</code>… so your own words wrap around the parts that have to stay live. Every section keeps its own logic — the tracker mode still rewrites “About” and “Features”, the statistics widget still needs its own setting — so <strong>hiding a section here is not the same as switching its feature off</strong>, and dragging one back does not switch it on. The editor says which is which on each row.',
    'settings.home_meta_default' => 'Sections in the order they ship in, nothing hidden, headings unchanged.',
    'settings.home_meta_hidden_many' => ':n sections hidden',
    'settings.home_meta_hidden_one' => '1 section hidden',
    'settings.home_meta_renamed_many' => ':n headings renamed',
    'settings.home_meta_renamed_one' => '1 heading renamed',
    'settings.home_meta_reordered' => 'reordered',
    'settings.home_meta_tagline' => 'custom tagline',
    'settings.home_title' => 'Home page layout',
    'settings.home_view' => 'View',
    'settings.homelayout_add' => 'Add a section',
    'settings.homelayout_close' => 'Close',
    'settings.homelayout_reset' => 'Restore built-in layout',
    'settings.homelayout_save' => 'Save',
    'settings.homelayout_tagline' => 'Line under the site name',
    'settings.homelayout_title' => 'Home page layout',
    'settings.index_enable' => 'Enable Index',
    'settings.index_files_days' => '(days)',
    'settings.index_files_keep' => 'Keep File Lists',
    'settings.index_files_keep_hint' => 'The worker also honours <code>index_keep_files</code> in its own conf.',
    'settings.index_files_keep_no' => 'No (name/size only)',
    'settings.index_files_poll_keep' => 'Keep poll history',
    'settings.index_files_poll_keep_hint_1' => 'One row per poll, behind the <strong>scrape coverage</strong> chart on the',
    'settings.index_files_poll_keep_hint_2' => ': how much of the tracker each poll actually delivered. At a 30-minute poll that is 48 rows a day &mdash; 90 days is about 4&nbsp;300 rows, so this costs nothing worth thinking about.',
    'settings.index_files_poll_keep_link' => 'Index page',
    'settings.index_files_title' => 'Index file lists',
    'settings.index_grace' => 'Grace (days)',
    'settings.index_grace_hint' => 'A new hash is dropped after this unless its metadata resolves.',
    'settings.index_intro_1' => 'A catalogue of info hashes <strong>seen on the tracker</strong> (mostly during OPEN hours, when the whole swarm is served), browsable at',
    'settings.index_intro_2' => '<strong>This is not a whitelist</strong> &mdash; nothing here is served or written to the accesslist; it is a read-only catalogue with metadata, S/L, search and a <em>Promote &rarr; whitelist</em> action. The janitor polls a full scrape (<code>GET&nbsp;/scrape</code>) every <em>Poll interval</em>, keeps hashes with at least <em>Min seeders</em>, and the metadata worker resolves names in the background (second queue, below the whitelist &mdash; needs DB grants, see <code>worker/README.md</code>). <strong>Measure the full-scrape cost during OPEN hours before enabling on a busy tracker.</strong>',
    'settings.index_intro_link' => 'Index',
    'settings.index_max_rows' => 'Max Rows (cap)',
    'settings.index_max_rows_hint' => 'Oldest unprotected rows are pruned above this.',
    'settings.index_meta_auto' => 'Auto-queue Metadata',
    'settings.index_meta_auto_hint' => 'When on, every observed hash without metadata is queued automatically (spread over ~1&nbsp;h, best seeded first) and the daily budget is <strong>ignored</strong>. Mind the DHT load on a big index.',
    'settings.index_meta_auto_no' => 'No (daily budget only)',
    'settings.index_meta_auto_yes' => 'Yes (queue every new hash)',
    'settings.index_meta_budget' => 'Metadata Budget (per day)',
    'settings.index_meta_budget_hint' => 'Rows queued for metadata per day, spread across 24&nbsp;h. 0 = never auto-fetch.',
    'settings.index_min_seeders' => 'Min Seeders to Index',
    'settings.index_min_seeders_hint' => 'Drop the dead-swarm tail. 1 = at least one seeder.',
    'settings.index_no' => 'No',
    'settings.index_poll_budget' => 'Poll Time Budget (s)',
    'settings.index_poll_budget_hint' => 'Wall-clock cap per poll; a huge scrape is processed partially.',
    'settings.index_poll_interval' => 'Poll Interval (min)',
    'settings.index_poll_interval_hint' => '5&ndash;1440. OpenTracker\'s modest-fullscrape limit is 5&nbsp;min/IP.',
    'settings.index_protect' => 'Protect (days)',
    'settings.index_protect_hint' => 'A resolved hash lives this long; extended while it still has seeders.',
    'settings.index_source_url' => 'Full-scrape Source URL',
    'settings.index_source_url_hint' => 'OpenTracker <code>/scrape</code> with no info_hash = full scrape. Localhost recommended.',
    'settings.index_title' => 'Index (observed hashes)',
    'settings.index_worker_conc' => 'Worker parallel fetches',
    'settings.index_worker_conc_hint' => 'How many hashes the worker resolves at once, across both queues. <strong>1&ndash;64</strong>, applied within ~60&nbsp;s &mdash; no restart.',
    'settings.index_worker_conc_more' => 'What it costs',
    'settings.index_worker_conc_more_body' => 'Each fetch is one libtorrent handle holding a small set of DHT and peer connections, so the ceiling here is file descriptors and memory, not libtorrent: at the top end expect a few hundred sockets, a few hundred MB, and outbound traffic to match. Raise it because this machine has spare capacity, not because the number is available.',
    'settings.index_worker_conc_note' => '(empty = worker config)',
    'settings.index_worker_conc_ph' => 'e.g. 8',
    'settings.index_yes' => 'Yes',
    'settings.iplists_capacity_hint' => '<strong>A network, not an address.</strong> China’s zone file from ipdeny is <strong>8&nbsp;810</strong> lines and covers <strong>343&nbsp;million</strong> addresses — so this ceiling holds about <strong>28 countries that size</strong>, and blocking one costs 3&nbsp;% of it. The limit is on the ruleset, which nftables loads as a single transaction; it is not a limit on how much of the internet you can refuse. Each list shows both numbers on the',
    'settings.iplists_capacity_hint_link' => 'Traffic page',
    'settings.iplists_capacity_label' => 'How much this can hold',
    'settings.iplists_capacity_value' => ':n networks',
    'settings.iplists_enabled_hint' => 'Off clears the sets from the firewall without deleting anything you imported. The lists live inside the inbound limit’s table, so the limit (or the counters) has to be running for them to be loaded at all.',
    'settings.iplists_heading' => 'Address lists (allow / block)',
    'settings.iplists_intro' => '<strong>Trusted addresses</strong> above is a box you type a handful of addresses into. This is the same idea at the scale an operator needs: whole networks, whole countries, kept in a file or fetched from a URL such as <code>ipdeny.com/ipblocks/data/countries/cn.zone</code> and refreshed on a timer. The lists themselves are managed on the',
    'settings.iplists_intro_after' => '— this is only the master switch and the default refresh interval.',
    'settings.iplists_intro_link' => 'Traffic page',
    'settings.iplists_kinds' => 'Three kinds, applied in this order: <strong>allow</strong> is never dropped whatever else says; <strong>block</strong> is dropped always; <strong>block under pressure</strong> is dropped only when the machine is busy — those addresses get a budget a fifth the size of everyone else’s, so at rest they are untouched and under load they are refused first. Anything you typed into Trusted addresses wins over every list.',
    'settings.iplists_label' => 'Address lists',
    'settings.iplists_off' => 'Off — the firewall carries no lists',
    'settings.iplists_on' => 'On — enforce the enabled lists',
    'settings.iplists_ttl_hint' => 'The default offered when you add a URL list; each list keeps its own value. 720 is twelve hours. A country zone changes a few times a year, so downloading it more often than that is rude to whoever is hosting it.',
    'settings.iplists_ttl_label' => 'Refresh downloaded lists every',
    'settings.iplists_ttl_label_sub' => '(minutes)',
