    'settings.lang_upload_dropped' => ':count keys were dropped because their text carried markup that is not allowed: :keys',
    'settings.langdup_cancel' => 'Cancel',
    'settings.langdup_code' => 'New code',
    'settings.langdup_code_hint' => 'Two or three letters, as in <code>de</code>, <code>fr</code>, <code>ast</code>.',
    'settings.langdup_intro_after' => 'is copied to a new code. The copy starts <strong>switched off</strong>, so it can be finished before anyone sees it.',
    'settings.langdup_intro_before' => 'Every string from',
    'settings.langdup_submit' => 'Copy',
    'settings.langdup_title' => 'Copy a language',
    'settings.languages_auto' => 'Follow the browser',
    'settings.languages_auto_check' => 'Use <code>Accept-Language</code> when nobody has chosen',
    'settings.languages_auto_hint' => 'Only within “for accounts”, and only when there is no saved choice. Setting the site language to <em>Automatic</em> does the same thing more plainly.',
    'settings.languages_col_accounts' => 'For accounts',
    'settings.languages_col_accounts_title' => 'A user may pin it to their account; also what automatic matching may pick',
    'settings.languages_col_completeness' => 'Completeness',
    'settings.languages_col_language' => 'Language',
    'settings.languages_col_offered' => 'Offered',
    'settings.languages_col_offered_title' => 'Exists for visitors at all',
    'settings.languages_col_switcher' => 'In the switcher',
    'settings.languages_col_switcher_title' => 'Shown by the header switcher',
    'settings.languages_col_vs' => 'vs',
    'settings.languages_default' => 'Site language',
    'settings.languages_default_hint' => 'What a visitor gets before they choose anything. A signed-in account’s own choice, and an explicit <code>?lang=</code>, both outrank this.',
    'settings.languages_download_template' => 'Download the English file to translate',
    'settings.languages_install' => 'Install a language',
    'settings.languages_intro1' => 'The panel ships with <strong>English</strong> and <strong>Polish</strong>. Any file dropped into <code>lang/</code> is a language — install one below from a JSON export, or copy an existing one and edit the copy. A key a translation is missing falls back to English, so a partial translation degrades into readable English rather than into blanks.',
    'settings.languages_intro2' => '<strong>Three lists, and they are not the same question.</strong> <em>Offered</em> decides which languages exist for visitors at all; <em>in the switcher</em> decides which the header control shows; <em>for accounts</em> decides which a user may pin to their account — and that is also the set automatic browser matching may pick from. A language kept out of the last two is still reachable by an explicit <code>?lang=</code> link: hiding a control is not the same as withdrawing a translation.',
    'settings.languages_not_writable' => 'The <code>lang/</code> directory is not writable by the web user, so installing or copying a language will fail. On Debian: <code>sudo chown www-data lang</code>.',
    'settings.languages_title' => 'Languages',
    'settings.langup_cancel' => 'Cancel',
    'settings.langup_drop_aria' => 'Choose or drop the JSON file',
    'settings.langup_drop_choose' => 'Choose a file',
    'settings.langup_drop_or' => 'or drop it here',
    'settings.langup_drop_sub' => 'A JSON file of "key": "text" pairs — export one above to start from.',
    'settings.langup_or_code' => 'or a code:',
    'settings.langup_pick' => 'Choose a language…',
    'settings.langup_step1' => 'Start from an existing file',
    'settings.langup_step1_text' => 'Download English (or any installed language) from the table, translate the values, and keep the keys exactly as they are — a key that changed is a string that falls back to English.',
    'settings.langup_step2' => 'Which language is it',
    'settings.langup_step3' => 'The translated file',
    'settings.langup_submit' => 'Install',
    'settings.langup_title' => 'Install a language',
    'settings.limits_admin_near_pages' => '“Near pages” radius (admin)',
    'settings.limits_admin_near_pages_hint' => 'Whitelist / Index bulk tools: <em>Near pages</em> covers the current page ± this many pages (same search, filters and sort).',
    'settings.limits_blacklist_path' => 'Blacklist file path',
    'settings.limits_blacklist_test' => 'Test',
    'settings.limits_items_per_page' => 'Reports per page (admin)',
    'settings.limits_max_appeal_message_length' => 'Max appeal reason length',
    'settings.limits_max_magnet_link_length' => 'Max magnet link length',
    'settings.limits_max_message_length' => 'Max message length',
    'settings.limits_rate_limit' => 'Reports per hour (per IP)',
    'settings.limits_rate_limit_appeal' => 'Appeals / hour (per IP)',
    'settings.limits_rate_limit_block_check' => 'Block lookups / hour (per IP)',
    'settings.limits_rate_limit_status' => 'Status checks / hour (per IP)',
    'settings.limits_title' => 'Rate Limits & Blacklist',
    'settings.limits_zero_off' => '(0 = off)',
    'settings.limits_zero_unlimited' => '(0 = unlimited)',
    'settings.livesync_bind_ip' => 'This machine, inside the tunnel',
    'settings.livesync_bind_ip_hint' => 'A private address on a tunnel interface. A public one is refused.',
    'settings.livesync_bind_ip_ph' => 'e.g. 10.9.0.1',
    'settings.livesync_cmd' => 'Helper command',
    'settings.livesync_cmd_hint' => 'Empty = the feature does not exist: no card, no polling, no <code>sudo</code>.',
    'settings.livesync_cmd_ph' => 'e.g. sudo -n /usr/local/sbin/tracker-livesync.sh',
    'settings.livesync_enabled' => 'Enabled',
    'settings.livesync_enabled_hint' => 'Turning this on only shows the card; arming it is a separate, password-confirmed action on the',
    'settings.livesync_enabled_hint_link' => 'Traffic page',
    'settings.livesync_intro_p1' => 'Two opentrackers on <strong>two machines</strong> telling each other who is in which swarm, live. This is <em>not</em> federation: federation moves metadata between panels over HTTPS with a key, this moves the peers themselves between trackers. Neither replaces the other, and on a single machine this does nothing at all — there is nobody to sync with. <strong>Off by default.</strong>',
    'settings.livesync_intro_p2' => '<strong>The protocol has no authentication and no encryption.</strong> Anything that can reach the port can inject peers into every swarm this tracker serves, so the helper <strong>refuses</strong> to arm unless the address belongs to a tunnel interface. There is no override for that, on purpose. The panel does not set up WireGuard for you either — generating a private key and writing it into <code>/etc</code> is a bigger claim on the machine than anything else here makes, and it would be doing it without being able to see the other end. Press <strong>Test</strong> and it prints the commands.',
    'settings.livesync_no' => 'No',
    'settings.livesync_peer_ip' => 'The other tracker, inside the tunnel',
    'settings.livesync_peer_ip_ph' => 'e.g. 10.9.0.2',
    'settings.livesync_port' => 'Sync port (UDP)',
    'settings.livesync_port_hint' => 'Its own port, not the tracker\'s 6969.',
    'settings.livesync_test_btn' => 'Test',
    'settings.livesync_test_ok' => 'Live peer sync can be armed from here.',
    'settings.livesync_title' => 'Live peer sync',
    'settings.livesync_yes' => 'Yes',
    'settings.mail_domain_not_allowed' => '(not allowed any more)',
    'settings.mail_from' => 'Sender address (From)',
    'settings.mail_from_hint' => 'All outgoing mail (resets, verifications, notices) is sent FROM this address; replies still go to Site Email. Leave the left box empty to send from Site Email. The domain list is fixed to the Site URL host and its parent domains — anything else breaks SPF/DKIM/DMARC alignment. Best deliverability: the domain your mail server signs DKIM for and has an SPF record on (usually the root domain).',
    'settings.mail_from_hint_nodomain' => 'Set a proper <strong>Site URL</strong> (a domain, not an IP) first — the sender domain is then picked from that domain and its parents. Until then this is a free-text field and the value is not domain-checked.',
    'settings.mail_from_sub' => '(empty = Site Email)',
    'settings.mail_heading' => 'Contact & Email',
    'settings.mail_hmac' => 'HMAC Secret (for unsubscribe tokens)',
    'settings.mail_local_ph' => 'noreply',
    'settings.mail_obfuscate' => 'Obfuscate Email',
    'settings.mail_show_contact' => 'Show Contact',
    'settings.mail_site_email' => 'Site Email',
    'settings.mail_site_email_sub' => '(public contact; replies go here)',
    'settings.net_auto_cpu_cores_hint' => 'This machine has <strong>:cores</strong> cores, so :pct % means a load average above <strong>:load</strong>.',
    'settings.net_auto_cpu_hint' => 'When the 1-minute load average per core is above this, the automatic mode tightens even if the packet rate is under target.',
    'settings.net_auto_cpu_label' => 'CPU guard',
    'settings.net_auto_cpu_label_sub' => '(% load per core)',
    'settings.net_auto_heading' => 'Automatic mode',
    'settings.net_auto_heading_sub' => '(off by default)',
    'settings.net_auto_intro' => 'Once a minute the janitor compares the packets/second that actually reached the tracker with your target and moves the limit by ±10 % inside the band below. It takes <strong>three</strong> samples in a row on the same side before anything moves (so one spike changes nothing), and there is a two-minute cool-down between moves. Needs both the monitor and the inbound limit switched on.',
    'settings.net_auto_label' => 'Automatic mode',
    'settings.net_auto_max_hint' => '… and never loosens above this.',
    'settings.net_auto_max_label' => 'Band: maximum',
    'settings.net_auto_min_hint' => 'The automatic mode never throttles below this.',
    'settings.net_auto_min_label' => 'Band: minimum',
    'settings.net_auto_off' => 'Disabled',
    'settings.net_auto_on' => 'On — move the limit for me',
    'settings.net_auto_target_hint' => 'How many packets a second you are willing to hand to OpenTracker. Above it the limit tightens, comfortably below it (−20 %) it loosens.',
    'settings.net_auto_target_label' => 'Target',
    'settings.net_auto_target_label_sub' => '(packets/second)',
    'settings.net_avail_test_btn' => 'Test firewall access',
    'settings.net_avail_test_hint' => 'Read-only: checks <code>nft</code>, the sudoers rule and whether the rule would survive a reboot. It never loads or removes anything.',
    'settings.net_avail_test_label' => 'Availability test',
    'settings.net_blocked' => 'Blocked addresses',
    'settings.net_blocked_hint' => 'The mirror image of the box above, and it exists for one case lists cannot express: <strong>&ldquo;allow all of Poland, except these three hosts&rdquo;</strong>. An allow list is matched before a block list, so a host inside an allowed range can never be stopped by another list &mdash; but it is stopped here.',
    'settings.net_blocked_more' => 'The order everything is matched in',
    'settings.net_blocked_more_1' => '<strong>1. Trusted addresses</strong> &mdash; accepted, whatever anything else says. <strong>2. Blocked addresses (this box)</strong> &mdash; dropped, ahead of every list. <strong>3. Allow lists</strong> &mdash; accepted. <strong>4. Block lists</strong> &mdash; dropped. <strong>5. Block-under-pressure lists</strong> &mdash; given a fifth of the general budget. <strong>6. The inbound limit</strong> &mdash; everyone else. So an address in both boxes is trusted: the first match wins and the panel says so on the',
    'settings.net_blocked_more_2' => 'rather than leaving you to work it out. Same cap as above (:max), same validation here and again in the root helper. Whole countries belong in a <em>list</em> on the Traffic page, not in this box.',
    'settings.net_blocked_note' => '(always dropped)',
    'settings.net_burst_hint' => 'How far over the budget a short spike may go before packets are dropped. 100 is a sane default; 5 makes the limit bite almost immediately.',
    'settings.net_burst_label' => 'Burst',
    'settings.net_burst_label_sub' => '(packets)',
    'settings.net_cmd_hint' => 'Only letters, digits, space and <code>_ . / -</code> — no shell metacharacters, exactly like the mode switch command above.',
    'settings.net_cmd_label' => 'Root helper command',
    'settings.net_cmd_label_sub' => '(the action arguments are appended automatically; empty = feature disabled)',
    'settings.net_cmd_ph' => 'e.g. :cmd',
    'settings.net_in_force' => 'In force: :n',
    'settings.net_install_once' => 'Install it once, on the server',
    'settings.net_intro_1' => 'Two different problems, two different levers. <strong>Inbound</strong> (this section): packets dropped by the firewall never reach OpenTracker, so a swarm that keeps hammering the port costs no CPU. <strong>Outbound</strong> (<code>tools/opentracker/egress-budget/ottrack.nft</code>): capping what the tracker <em>answers</em> is what keeps the rest of the machine reachable. The panel drives the first and shows the second side by side on the',
    'settings.net_intro_2' => 'Everything here is applied through the root helper <code>tools/opentracker/tracker-netlimit.sh</code>, which writes <strong>one file</strong> (<code>/etc/nftables.d/ottrack-in.nft</code>) in <strong>its own nftables table</strong> (<code>inet ottrack_in</code>). Your distribution\'s <code>inet filter</code> table and any rule you added there by hand are never read or written &mdash; undoing all of this is one click, or <code>nft delete table inet ottrack_in</code>.',
    'settings.net_intro_link' => 'Traffic page',
    'settings.net_keep' => 'Keep samples for',
    'settings.net_keep_hint' => 'At one sample a minute that is ~1 440 rows a day &mdash; 14 days is about 20 000 tiny rows.',
    'settings.net_limit_label' => 'Inbound limit',
    'settings.net_limit_off' => 'Off — nothing is dropped',
    'settings.net_limit_on' => 'Enabled',
    'settings.net_monitor' => 'Traffic monitor',
    'settings.net_monitor_hint' => 'Turn it on <em>first</em>: the suggested threshold is computed from what was measured, not guessed. The counters live in the firewall, so the Traffic page offers <strong>Start counting</strong> &mdash; the same table with <strong>no drop rule at all</strong>, which measures without throttling anything.',
    'settings.net_monitor_off' => 'Disabled',
    'settings.net_monitor_on' => 'On &mdash; record packets/second',
    'settings.net_not_address' => 'Not an address, ignored:',
    'settings.net_port' => 'Tracker UDP port',
    'settings.net_port_hint' => 'The port in your announce URL (<code>6969</code> by default). Only this port is touched.',
    'settings.net_pps_hint' => 'Everything above this is dropped before OpenTracker sees it. :min–:max.',
    'settings.net_pps_label' => 'Packets / second',
    'settings.net_sample' => 'Sample every',
    'settings.net_sample_hint' => 'The janitor timer runs every minute, so anything below 60 s samples at most once a minute anyway.',
    'settings.net_seconds' => '(seconds)',
    'settings.net_throttle_heading' => 'Inbound limit',
    'settings.net_throttle_heading_sub' => '(the throttle)',
    'settings.net_throttle_intro' => 'Saving here records what the panel <em>should</em> load — it does not touch the firewall. Loading, previewing and removing the rule live on the',
    'settings.net_throttle_intro_after' => ', behind the admin password, with the measured median / P95 / peak drawn on the slider.',
    'settings.net_throttle_intro_link' => 'Traffic page',
    'settings.net_title' => 'UDP traffic & rate limit',
    'settings.net_trusted' => 'Trusted addresses',
    'settings.net_trusted_hint' => 'IPv4 or IPv6, plain or CIDR, separated by commas, spaces or newlines. Packets from these sources are <strong>counted but never dropped</strong> &mdash; they skip the budget entirely.',
    'settings.net_trusted_more' => 'What this is for, and what it costs',
    'settings.net_trusted_more_body' => 'A rate limit cannot tell which packets matter. If this machine also runs a game server, or is monitored from a fixed address, or you reach it over SSH from one place, those sources should never be collateral damage of a swarm. Each entry becomes an element of an nftables set and costs one hash lookup, so the list is free at any size worth having &mdash; the cap is <strong>:max</strong>, and it is a cap on judgement rather than on performance: this is an exemption from the machine\'s own protection, and a list nobody reviews is a hole. A source listed here can send at any rate it likes. The addresses are validated here <em>and again</em> in the root helper, which is what actually writes them into the firewall; anything unrecognised is dropped with a note rather than failing the whole apply.',
    'settings.net_trusted_note' => '(never rate-limited)',
    'settings.no' => 'No',
    'settings.opt_disabled' => 'Disabled',
    'settings.opt_enabled' => 'Enabled',
    'settings.ot_auto_reload' => 'Auto-reload blacklist',
    'settings.ot_auto_reload_hint' => 'Auto <code>systemctl reload</code> after every block/unblock/restore so changes apply instantly.',
    'settings.ot_auto_reload_no' => 'No &mdash; manual only',
    'settings.ot_auto_reload_yes' => 'Yes &mdash; SIGHUP on change',
    'settings.ot_bl_danger' => 'Blacklist changes → red',
    'settings.ot_bl_danger_hint' => 'At or above this many, the alert turns red (restart required).',
    'settings.ot_bl_warn' => 'Blacklist changes → orange',
    'settings.ot_bl_warn_hint' => 'Pending blacklist changes since last start before a restart is recommended.',
    'settings.ot_cluster_enabled' => 'Enabled',
    'settings.ot_cluster_enabled_hint' => 'Turning it on only shows the card; it creates nothing.',
    'settings.ot_cluster_no' => 'No',
    'settings.ot_cluster_port_base' => 'First extra port',
    'settings.ot_cluster_port_base_hint' => 'Empty = the panel proposes the first free port next to the tracker’s own. Ports below 1024 are refused.',
    'settings.ot_cluster_port_base_ph' => '(next to the primary’s)',
    'settings.ot_cluster_test' => 'Test',
    'settings.ot_cluster_test_hint' => 'The Test button also checks something the panel cannot see by itself: whether the <em>installed</em> <code>/usr/local/sbin/tracker-mode.sh</code> understands <code>--all</code>. No deploy updates that file, and if the nightly schedule calls a flag the installed copy does not know, the scheduled whitelist hours simply never begin — silently, every night.',
    'settings.ot_cluster_yes' => 'Yes',
    'settings.ot_cpu_affinity' => 'CPU affinity',
    'settings.ot_cpu_affinity_hint' => 'Empty = every core. Pinning helps only when something else on this machine needs cores kept free for it. <strong>Needs a restart.</strong>',
    'settings.ot_cpu_affinity_ph' => 'e.g. 2-5',
    'settings.ot_cpu_weight' => 'CPU weight',
    'settings.ot_cpu_weight_hint' => 'Share of CPU against other services under contention. 100 is the default for everything, so 200 means “twice the forum\'s”.',
    'settings.ot_intro_1' => 'Define the systemd unit of your tracker (e.g. <code>opentracker</code> or <code>opentracker.service</code>). When set, <strong>Reload</strong> and <strong>Restart tracker</strong> buttons appear on the Dashboard, together with smart recommendations that turn',
    'settings.ot_intro_2' => 'when a restart is advisable (after blacklist changes, or a long uptime). <strong>Reload</strong> runs <code>systemctl reload &lt;name&gt;</code> &mdash; a <strong>SIGHUP</strong> that makes OpenTracker re-read its white/blacklist with <em>no downtime</em>; <strong>Restart</strong> runs <code>systemctl restart &lt;name&gt;</code> (brief downtime). The web/PHP user must be allowed to run those commands &mdash; use the <strong>Test</strong> buttons below and see the README (sudoers). Leave the name empty to hide the buttons entirely.',
    'settings.ot_intro_or' => 'or',
    'settings.ot_intro_orange' => 'orange',
    'settings.ot_intro_red' => 'red',
    'settings.ot_nice' => 'Nice',
    'settings.ot_nice_hint' => 'Lower = more CPU when the box is busy. −2 is what the install notes recommend; below −5 you start competing with the kernel\'s own threads.',
    'settings.ot_nofile' => 'Open file limit',
    'settings.ot_nofile_hint' => '<code>LimitNOFILE</code>. <strong>Needs a restart.</strong>',
    'settings.ot_perf_cmd' => 'Helper command',
    'settings.ot_perf_cmd_hint' => 'Needs a sudoers rule: <code>www-data ALL=(root) NOPASSWD: /usr/local/sbin/tracker-instance.sh</code>. Empty = the panel can only read, never change.',
    'settings.ot_perf_cmd_ph' => 'e.g. sudo -n /usr/local/sbin/tracker-instance.sh',
    'settings.ot_perf_intro_a' => 'The knobs that already exist on any systemd machine, and they are worth nearly all of the available gain at nearly none of the risk. Everything the panel writes goes into <strong>one file it owns</strong> — <code>90-tracker-panel.conf</code> in the unit\'s drop-in directory. <code>override.conf</code> and <code>limits.conf</code> were put there by the installer or by hand and are <strong>never touched</strong>; undo is deleting the panel\'s one file, which is what <em>Reset</em> does. <strong>Saving here changes nothing by itself</strong> — these values describe what you want, and the Apply button on the',
    'settings.ot_perf_intro_b' => '(admin password) is what puts them in force.',
    'settings.ot_perf_test_btn' => 'Test',
    'settings.ot_perf_title' => 'OpenTracker — performance',
    'settings.ot_perf_traffic_page' => 'Traffic page',
    'settings.ot_perm_test' => 'Permission test',
    'settings.ot_perm_test_hint' => 'Checks whether the web user may run the command (via <code>sudo -n -l</code>) &mdash; it does <strong>not</strong> restart or reload anything. Save the service name first. Fix instructions are shown if the test fails.',
    'settings.ot_perm_test_reload' => 'Test reload permission',
    'settings.ot_perm_test_restart' => 'Test restart permission',
    'settings.ot_service_name' => 'Service name',
    'settings.ot_service_name_hint' => 'Only letters, digits and <code>. _ @ -</code> are allowed.',
    'settings.ot_service_name_note' => '(empty = disabled)',
    'settings.ot_sudo' => 'Run via sudo',
    'settings.ot_sudo_hint' => 'Most setups need sudo: php-fpm runs unprivileged.',
    'settings.ot_sudo_no' => 'No &mdash; direct',
    'settings.ot_sudo_yes' => 'Yes &mdash; <code>sudo -n</code>',
    'settings.ot_thresholds' => 'Restart recommendation thresholds',
    'settings.ot_title' => 'OpenTracker Service',
    'settings.ot_udp_workers' => 'UDP workers',
    'settings.ot_udp_workers_hint' => '<code>listen.udp.workers</code> in opentracker\'s own config — written to <strong>both</strong> mode files so it cannot change when the tracker switches white/black. Empty leaves it alone. <strong>Read only at start-up: needs a restart.</strong>',
    'settings.ot_udp_workers_ph' => 'leave empty to keep',
    'settings.ot_uptime_danger' => 'Uptime days → red',
    'settings.ot_uptime_danger_hint' => 'Uptime warning turns red at this many days.',
    'settings.ot_uptime_warn' => 'Uptime days → orange',
    'settings.ot_uptime_warn_hint' => 'Recommend a restart once uptime reaches this many days.',
    'settings.pages_archive_appeals' => 'Auto-archive appeals',
    'settings.pages_archive_appeals_hint' => 'Automatically archive resolved appeals older than X days.',
    'settings.pages_archive_reports' => 'Auto-archive reports',
    'settings.pages_archive_reports_hint' => 'Automatically archive reviewed reports older than X days.',
    'settings.pages_badge_builtin' => 'built-in',
    'settings.pages_badge_draft' => 'draft — built-in page is live',
    'settings.pages_badge_live' => 'your version, live',
    'settings.pages_close' => 'Close',
    'settings.pages_edit' => 'Edit',
    'settings.pages_editor_title' => 'Page',
    'settings.pages_email_log' => 'Delete email log after',
    'settings.pages_email_log_hint' => 'Prune sent_emails rows older than X days. Off by default.',
    'settings.pages_email_log_sub' => '(0 = keep forever)',
    'settings.pages_format' => 'Format',
    'settings.pages_format_bbcode' => 'BBCode — no headings, large bold instead',
    'settings.pages_format_markdown' => 'Markdown — has headings',
    'settings.pages_heading' => 'Public Pages',
    'settings.pages_heading_2' => 'Site pages (Terms & Info)',
    'settings.pages_intro1' => '<strong>Terms of Service</strong> and <strong>Tracker Information</strong> ship as written pages and can be replaced with your own, using the same editor the whitelist descriptions and the bulk mail use — Markdown or BBCode, with a live preview. The built-in pages <em>rewrite themselves</em> when the tracker mode or the account system changes; a saved page does not, and <strong>Restore</strong> brings back the built-in one written for how the tracker is configured at that moment.',
    'settings.pages_intro2' => '<strong>One version per language.</strong> A visitor gets the version for their language; where none is published, they get the one for the site\'s default language, then English, then any other version that exists — and only if <em>nothing</em> is written do they get the built-in page. That order is deliberate: terms you actually wrote must never be quietly replaced by boilerplate because one translation is missing.',
    'settings.pages_intro3' => '<strong>Markdown is offered first</strong> for these two, and not by taste: the renderer has real headings in Markdown (<code>#</code>…<code>######</code>) and none at all in BBCode, where a heading can only be a larger bold line. A Terms page is mostly headings and numbered lists.',
    'settings.pages_lang_draft' => 'saved as a draft',
    'settings.pages_lang_live' => 'your version is live',
    'settings.pages_lang_none' => 'no version written yet',
    'settings.pages_meta_never' => 'Never edited — visitors see the page that ships with the panel.',
    'settings.pages_meta_written' => ':n of :total languages written.',
    'settings.pages_preview' => 'How it will look',
    'settings.pages_preview_frame' => 'Preview',
    'settings.pages_restore' => 'Restore built-in',
    'settings.pages_save' => 'Save',
    'settings.pages_title' => 'Site pages',
    'settings.pages_use_mine' => 'Use my version',
    'settings.pages_view' => 'View',
    'settings.pages_your_text' => 'Your text',
    'settings.pages_zero_disabled' => '(0 = disabled)',
    'settings.pc_markers_note' => 'Blocks wrapped in [[if:name]] … [[/if]] (or [[ifnot:name]]) appear only while that setting is on, so a page you save keeps following the tracker mode and the account system exactly as the built-in one does. Restore brings back the built-in text for this language, markers included.',
    'settings.probe_disabled' => 'Disabled',
    'settings.probe_enabled' => 'Enabled',
    'settings.probe_intro_p1' => 'Anybody can paste forty hex characters. Most of what a public whitelist accumulates is not abuse — it is hashes nobody is seeding, and hashes whose torrent never named this tracker. Each one becomes a row the accesslist carries for ever.',
    'settings.probe_intro_p2' => 'With this on, a new submission has to show two things before the tracker serves it: <strong>the metadata resolves</strong> (somebody really is sharing it) and <strong>a scrape finds at least one peer</strong> (and they are announcing here). It reuses the metadata worker rather than adding a second queue, but jumps the queue — a person is watching this one, and nothing else in the queue is. <strong>Off by default:</strong> it changes what registering <em>means</em>, and that is not something to inherit from an upgrade.',
    'settings.probe_max_batch' => 'Magnets verified at once, per submission',
    'settings.probe_max_batch_hint' => 'Five hundred rows in the priority lane are not resolved faster — they just make everyone wait together. Keep this at or below <em>Worker parallel fetches</em>.',
    'settings.probe_max_batch_ph' => 'e.g. 8 (defaults to the worker\'s concurrency)',
    'settings.probe_on_fail' => 'If the magnet never verifies',
    'settings.probe_on_fail_delete' => 'Remove the row',
    'settings.probe_on_fail_hint' => 'Deleting is the default here, unlike the dead-row rule: this row was never served, and nobody has come to rely on it.',
    'settings.probe_on_fail_keep' => 'Keep it, unserved, with the reason',
    'settings.probe_required' => 'Verify the magnet before serving it',
    'settings.probe_required_hint' => 'Existing rows are unaffected: everything registered before this counts as already accepted, so turning it on never unpublishes anything.',
    'settings.probe_subtitle' => 'Magnet check, peer verification and the proving queue',
    'settings.probe_timeout' => 'Verification timeout (minutes)',
    'settings.probe_timeout_hint' => 'Fetching metadata from the DHT is not instant. Too short and honest submissions fail.',
    'settings.probe_title' => 'Submissions must prove themselves',
    'settings.rep_anon_weight' => 'Weight of an anonymous vote (%)',
    'settings.rep_anon_weight_hint' => 'Against 100% for a signed-in account. 0 = anonymous votes are counted but change nothing.',
    'settings.rep_captcha_pts_vote' => 'CAPTCHA points per vote',
    'settings.rep_captcha_pts_vote_hint' => 'A vote adds this to the same score every other action feeds. Steady use is never interrupted; fifty votes in a minute meets a challenge, without anybody having to write a bot detector.',
    'settings.rep_enabled_hint' => 'Ratings apply to <strong>any hash the catalogue knows</strong>, not only registered ones — a torrent does not have to be on the whitelist to be rated.',
    'settings.rep_heading' => 'Ratings',
    'settings.rep_intro_1' => 'Up or down on a torrent, shown in the Info panel and optionally beside every search result. <strong>Off by default.</strong>',
    'settings.rep_intro_2' => '<strong>What a public voting button really is:</strong> the easiest thing on a site to automate. One loop, a thousand negatives, and the score means nothing for ever. Four things stand in the way here, because no single one holds: one vote per identity enforced by a <strong>unique key in the database</strong> (not a check in PHP, which is a race two requests can walk straight through), the shared rate limiter, the CAPTCHA points scheme this site already uses, and a weight that makes an anonymous vote count for less than an account\'s.',
    'settings.rep_intro_3' => '<strong>About attributing votes to an IP address:</strong> <code>REMOTE_ADDR</code> comes from the TCP connection and cannot be forged over the internet — forging it would mean completing a handshake from the forged address. Headers can be forged, and this panel only reads one when the request genuinely arrived from an address you listed under <em>Trusted proxy IPs</em>. What none of that fixes is one person with a VPN and a phone: IPv6 is bucketed to a /64 so a single allocation counts once, but a score built from anonymous votes is a weak signal and the panel will not pretend otherwise.',
    'settings.rep_min_votes' => 'Votes before a score is shown',
    'settings.rep_min_votes_hint' => 'Below this the panel says “too few ratings” instead of a number. “100% from one vote” and “100% from four hundred” are not the same fact.',
    'settings.rep_mode' => 'How people rate',
    'settings.rep_mode_hint' => 'Stars are stored in ten steps and shown as five, so half a star is a real value rather than something inferred. Switching mode does not delete anything, but the two scales are not comparable — ratings cast in one mode will read oddly in the other.',
    'settings.rep_mode_stars' => 'Five stars, in half steps',
    'settings.rep_mode_thumbs' => 'Up or down',
    'settings.rep_off' => 'Ratings are off',
    'settings.rep_on' => 'Ratings are on',
    'settings.rep_rate_per_hour' => 'Votes per hour, per voter',
    'settings.rep_show' => 'Show in search results',
    'settings.rep_show_column' => 'Also as a column in the list',
    'settings.rep_show_info' => 'Only in the Info panel',
    'settings.rep_who' => 'Who can rate',
    'settings.rep_who_all' => 'Anyone, including anonymous',
    'settings.rep_who_hint' => 'Anonymous voting is attributed to an address bucket, which one person can have several of. Open it knowing that.',
    'settings.rep_who_off' => 'Nobody — show scores only',
    'settings.rep_who_users' => 'Signed-in accounts',
    'settings.save_settings' => 'Save Settings',
    'settings.sched_all_day' => 'whitelist 00:00–24:00',
    'settings.sched_ends_next_day_at' => 'ends next day at ',
    'settings.sched_open_mode' => 'open (blacklist) mode',
    'settings.sched_same_day' => 'same day',
    'settings.sched_set_both_times' => 'set both times',
    'settings.schedule_desired_now' => 'Desired mode now:',
    'settings.schedule_disabled' => 'Disabled',
    'settings.schedule_enabled' => 'Scheduled mode',
    'settings.schedule_enabled_opt' => 'Enabled',
    'settings.schedule_intro_1' => 'Run the tracker in <strong>whitelist</strong> mode during the hours below and in <strong>open (blacklist)</strong> mode at every other moment.',
    'settings.schedule_intro_2' => 'The switch itself is done by the root helper below (it swaps the OpenTracker binary + config and restarts the service; argument <code>white</code> / <code>black</code>),',
    'settings.schedule_intro_3' => 'called by the janitor timer (<code>tools/janitor.php</code>, every minute) — never by a web request. While the schedule is ON the "Tracker mode" select above is',
    'settings.schedule_intro_4' => 'overridden by the schedule within a minute; bans are kept consistent between the whitelist (banned hashes) and the blacklist file at every switch.',
    'settings.schedule_intro_5' => 'Public registration stays open in both modes; hashes registered during open hours become active at the next whitelist window.',
    'settings.schedule_invalid' => 'invalid',
    'settings.schedule_kind_all' => 'Whitelist all day',
    'settings.schedule_kind_none' => 'Blacklist (open) all day',
