    'settings.schedule_last_switch' => 'Last switch:',
    'settings.schedule_next_change' => 'next change:',
    'settings.schedule_none' => 'none',
    'settings.schedule_off_note' => 'Schedule is off — the tracker stays in the mode selected above.',
    'settings.schedule_saved' => 'Saved schedule:',
    'settings.schedule_subtitle' => 'Whitelist during set hours, open otherwise',
    'settings.schedule_switch_at' => 'at',
    'settings.schedule_switch_cmd' => 'Mode switch command',
    'settings.schedule_switch_cmd_hint' => '(root helper; <code>white</code>/<code>black</code> is appended; empty = only flip the web setting)',
    'settings.schedule_switch_cmd_ph' => 'e.g. sudo -n /usr/local/sbin/tracker-mode.sh',
    'settings.schedule_th_day' => 'Day',
    'settings.schedule_th_from' => 'From',
    'settings.schedule_th_rule' => 'Rule',
    'settings.schedule_th_to' => 'To',
    'settings.schedule_title' => 'Scheduled tracker mode',
    'settings.schedule_tracker_is_in' => 'tracker is in',
    'settings.schedule_tz' => 'Timezone',
    'settings.schedule_window_hint' => 'A window starts on that weekday at <em>From</em>; when <em>To</em> ≤ <em>From</em> it ends on the <strong>next day</strong> at <em>To</em> (e.g. Mon 10:00 → 02:30 = Monday 10:00 until Tuesday 02:30). Outside every window the tracker runs <strong>OPEN (blacklist)</strong> mode.',
    'settings.search_aria' => 'Search settings',
    'settings.search_clear' => 'Clear search',
    'settings.search_no_match' => 'No setting matches',
    'settings.search_no_match_hint' => 'Try a shorter word — the search also knows synonyms (e.g. <em>bot</em>, <em>smtp</em>, <em>cron</em>, <em>hidden url</em>).',
    'settings.search_ph' => 'Search settings — try captcha, sender, timeout, whitelist…',
    'settings.site_announce_https' => 'Announce URL (HTTP/S)',
    'settings.site_announce_udp' => 'Announce URL (UDP)',
    'settings.site_github_hint' => 'Shown as the <strong>GitHub</strong> link in the footer. Point it at the <em>repository</em> of this tracker (so a visitor lands on the source, not on an account page); leave empty to hide the link.',
    'settings.site_github_url' => 'GitHub URL',
    'settings.site_github_url_sub' => '(the project repository)',
    'settings.site_heading' => 'Site Configuration',
    'settings.site_name' => 'Site Name',
    'settings.site_url' => 'Site URL',
    'settings.stats_cache_ttl' => 'Cache Lifetime / TTL (Sec)',
    'settings.stats_cache_ttl_hint' => 'Shared server-side lifetime of the fetched stats. While the cache is younger than this, everyone is served the same data and the upstream tracker is <strong>not</strong> re-fetched. Set this ≥ the typical upstream fetch time (often 30–60s) so reloads don\'t trigger constant re-syncs.',
    'settings.stats_enable' => 'Enable Tracker Stats',
    'settings.stats_home_interval' => 'Home Refresh Interval (Sec)',
    'settings.stats_home_interval_hint' => 'How often the homepage widget polls for fresh data.',
    'settings.stats_livesync' => 'Live Syncs Counter',
    'settings.stats_livesync_hint' => 'OpenTracker\'s livesync is 0 on single-node setups. “Count our cache refreshes” repurposes the <em>Live Syncs</em> stat as the number of times we refreshed the cache since the tracker last started (auto-resets on tracker restart).',
    'settings.stats_livesync_local' => 'Count our cache refreshes',
    'settings.stats_livesync_upstream' => 'Tracker value (raw, often 0)',
    'settings.stats_loading_hint' => 'Define a delay range in milliseconds (e.g. 100 to 2000). The server will pick a random duration within this range for visual animation simulation. Set both fields to the same value for a fixed delay.',
    'settings.stats_max_loading' => 'Max Loading Delay (ms)',
    'settings.stats_min_loading' => 'Min Loading Delay (ms)',
    'settings.stats_opt_no' => 'No',
    'settings.stats_opt_yes' => 'Yes',
    'settings.stats_page_interval' => 'Stats Page Refresh Interval (Sec)',
    'settings.stats_page_interval_hint' => 'How often the /?action=stats page re-checks the cache. Cheap cache hits — does not re-fetch upstream.',
    'settings.stats_peer_label_style' => 'Seeds/Leechers Label Style',
    'settings.stats_peer_label_style_hint' => 'How the Seeds/Leechers cards on the stats page are labelled.',
    'settings.stats_pls_absolute' => 'Absolute (of N peers)',
    'settings.stats_pls_peers_card' => 'Peers card (leechers · seeds)',
    'settings.stats_pls_percent' => 'Percent of total peers (44% / 56%)',
    'settings.stats_show_home' => 'Show on Homepage',
    'settings.stats_source_url' => 'Stats Source URL',
    'settings.stats_timeout' => 'Request Timeout (Sec)',
    'settings.stats_title' => 'Tracker Statistics',
    'settings.sysctl_cmd' => 'Helper command',
    'settings.sysctl_cmd_hint' => 'Empty = the feature does not exist: no card, no polling, no <code>sudo</code>. Install <code>tools/opentracker/tracker-sysctl.sh</code> and its <code>sudoers.d</code> rule first, then press Test.',
    'settings.sysctl_cmd_ph' => 'e.g. sudo -n /usr/local/sbin/tracker-sysctl.sh',
    'settings.sysctl_confirm_seconds' => 'Confirmation window (s)',
    'settings.sysctl_confirm_seconds_hint' => 'How long an armed change waits for your confirmation before undoing itself. Rounded to whole minutes, because the fallback watchdog is the janitor and it runs once a minute — a 30-second promise it cannot keep would still read as a guarantee.',
    'settings.sysctl_enabled' => 'Enabled',
    'settings.sysctl_enabled_hint' => 'Off by default. Turning it on only shows the card; it changes nothing.',
    'settings.sysctl_intro' => 'The eight kernel settings that decide how many announces survive a burst — the socket buffers, the per-CPU packet queue and the machine-wide UDP memory pool. This is the first thing the panel touches that is <strong>not</strong> the tracker’s own: these belong to the whole machine, which here also runs mail, the forum, the file service and the database they share. So nothing is applied by saving. A change is <em>armed</em>, takes effect while you watch it, and <strong>puts itself back automatically unless you confirm</strong> — the undo is scheduled through systemd before the change is made, so it does not need this panel, the database, or an administrator who can still log in. Nothing is written to <code>/etc</code> until you confirm either, so until then a reboot also undoes it. The values live on the',
    'settings.sysctl_intro_link' => 'Traffic page',
    'settings.sysctl_intro_tail' => ', next to the counters that say which of them is worth touching at all.',
    'settings.sysctl_no' => 'No',
    'settings.sysctl_test' => 'Test',
    'settings.sysctl_title' => 'Kernel network buffers',
    'settings.sysctl_yes' => 'Yes',
    'settings.timeline_buttons' => 'Buttons offered',
    'settings.timeline_buttons_hint' => 'Unchecked ranges disappear from the chart everywhere (stats page, Index, Whitelist). Clearing them all falls back to the full set; the default range must stay checked or the first remaining button wins.',
    'settings.timeline_custom' => 'Custom span slider',
    'settings.timeline_custom_hint' => 'Adds a slider that sweeps any span from 1 h to 5 years. These replies are computed per request (the fixed ranges are served from a 30 s file cache), so leave it off on a busy public page.',
    'settings.timeline_custom_yes' => 'Yes — add a "Custom" button',
    'settings.timeline_default_range' => 'Default range',
    'settings.timeline_default_range_hint' => 'The range a visitor\'s first view opens on (their own last pick is then remembered in the browser). A short default is the cheapest one to serve.',
    'settings.timeline_enable' => 'Enable Timeline',
    'settings.timeline_interval' => 'Sample Interval (Sec)',
    'settings.timeline_interval_hint' => 'One sample per this many seconds (30–600). 60 matches the janitor timer.',
    'settings.timeline_intro' => 'Records the tracker statistics over time (seeds, leechers, peers, torrents, announce rates, tracker mode) and draws a stock-style chart on the public <strong>/?action=stats</strong> page and on the admin Traffic page. Samples are taken by the <strong>janitor timer</strong> (<code>tools/janitor.php</code>, every minute — see README) and, for free, by every upstream refresh the stats page makes; roll-ups (5 min / 1 h) and retention run from the same timer. Requires <em>Tracker Statistics</em> above to be enabled with a valid Stats Source URL.',
    'settings.timeline_keep_days' => 'Keep 5-min Roll-ups (Days)',
    'settings.timeline_keep_days_hint' => '7–3650 days; hourly roll-ups are kept forever (~9 k rows/year).',
    'settings.timeline_public' => 'Public Chart',
    'settings.timeline_public_hint' => 'When off, the chart and the <code>stats_timeline</code> API answer only logged-in admins.',
    'settings.timeline_public_no' => 'No — admins only',
    'settings.timeline_public_yes' => 'Yes — on the stats page',
    'settings.timeline_ranges_head' => 'Range buttons',
    'settings.timeline_raw_days' => 'Keep Raw Samples (Days)',
    'settings.timeline_raw_days_hint' => 'Raw resolution (1–30 days); used by the 24 h view.',
    'settings.timeline_title' => 'Statistics Timeline',
    'settings.title' => 'Settings',
    'settings.transparency_enable' => 'Enable Transparency',
    'settings.transparency_per_page' => 'Results per page',
    'settings.transparency_title' => 'Transparency Page',
    'settings.tuner_enabled_hint' => 'Enabling it only shows the control; a run still needs the admin password.',
    'settings.tuner_enabled_opt' => 'Enabled — the button appears on Traffic',
    'settings.tuner_hard' => 'Hard stop',
    'settings.tuner_hard_hint' => 'An absolute floor under the whole thing, for a machine genuinely being driven into the ground. Well above anything normal here.',
    'settings.tuner_headroom' => 'Load a run may add',
    'settings.tuner_headroom_hint' => 'A run stops when load climbs more than this <strong>above where it started</strong>. Judged against the baseline on purpose: an absolute ceiling is meaningless on a machine whose ordinary working load is already near it — that is how every run here used to stop on its first step.',
    'settings.tuner_intro' => 'Finds where this machine\'s limits actually are, by moving the inbound limit through a few steps and watching what happens — including to <strong>everything else on the box</strong>. A formula can suggest a number from past traffic; only a run can answer “does raising this make the other services drop packets”, which is usually the real question.<br><strong>Off by default.</strong> The way back is written down before the first change, so the settings return even if the run is killed or the machine reboots — the janitor restores them. Nothing is applied automatically: a run ends exactly where it started and leaves a report.',
    'settings.tuner_label' => 'Stability probe',
    'settings.tuner_load_per_core' => '(load per core)',
    'settings.tuner_per_core' => '(per core)',
    'settings.tuner_python' => 'Python command',
    'settings.tuner_python_hint' => 'What the janitor runs <code>tools/tuner.py</code> with. Letters, digits and <code>_ . / -</code> only.',
    'settings.tuner_title' => 'Stability probe',
    'settings.twofa_hint' => 'A six-digit code from an authenticator app (TOTP, RFC&nbsp;6238 — Google Authenticator, Aegis, 1Password, anything) on top of the password. <strong>Off by default.</strong> The secret lives in <code>config/admin_2fa.json</code>, beside the password hash and away from the settings table that every backup dumps. Turning it <em>off</em> needs the password <strong>and</strong> a current code: this exists for the case where somebody else has the password, so the password alone must not be able to switch it off.',
    'settings.twofa_reading' => 'Reading…',
    'settings.twofa_title' => 'Two-factor authentication',
    'settings.users_default_group' => 'Default group (slug)',
    'settings.users_default_group_hint' => 'Granted to every new account (plus any group flagged “default”).',
    'settings.users_email_cooldown' => 'Email change cooldown (days)',
    'settings.users_email_cooldown_hint' => 'After a completed change the next one is blocked for this many days (anti-hijack). 0 = off. Changes are always confirmed from the OLD address first, then the NEW one.',
    'settings.users_email_verify' => 'Require email verification',
    'settings.users_email_verify_hint' => 'With Yes, registration requires an email and group permissions only apply after the confirmation link is clicked (the account page itself stays reachable; admins are exempt).',
    'settings.users_email_verify_no' => 'No — groups apply immediately',
    'settings.users_email_verify_yes' => 'Yes — unverified accounts act as guests',
    'settings.users_expiry_days' => 'Expiry warning (days)',
    'settings.users_expiry_days_hint' => 'Notify (+email when possible) this many days before a timed group ends. 0 = off.',
    'settings.users_intro_a' => 'Optional member system: registration + login (CAPTCHA-protected), groups with per-feature permissions, timed access (sellable via the <code>v1/users/*</code> API with a <em>users</em>-scope key), in-app notifications and a member search over the Index. Users and groups are managed on the',
    'settings.users_intro_b' => 'The <strong>guest</strong> group defines what anonymous visitors may see — with accounts <em>disabled</em> everything behaves exactly as before (public pages public, Index admin-only).',
    'settings.users_label' => 'User accounts',
    'settings.users_links' => 'Login / register links',
    'settings.users_links_hidden' => 'Hidden (direct URL only)',
    'settings.users_links_hint' => 'Hidden: <code>?action=login</code> / <code>?action=register</code> still work.',
    'settings.users_links_visible' => 'Visible in the menu',
    'settings.users_page_link' => 'Users page',
    'settings.users_registration' => 'Public registration',
    'settings.users_registration_closed' => 'Closed (admin / API only)',
    'settings.users_registration_hint' => 'Registration always requires a configured CAPTCHA.',
    'settings.users_registration_open' => 'Open',
    'settings.users_rl_login' => 'Logins / 15 min (per IP)',
    'settings.users_rl_preview' => 'Description previews / min (per IP)',
    'settings.users_rl_preview_hint' => 'The Preview button renders on the server, because that is the only place that can guarantee what comes out — which makes it a parser anybody can call.',
    'settings.users_rl_register' => 'Registrations / hour (per IP)',
    'settings.users_rl_search' => 'Searches / hour (per IP)',
    'settings.users_search' => 'Member search',
    'settings.users_search_disabled' => 'Disabled (even with permissions)',
    'settings.users_search_hint' => 'Master switch for <code>?action=search</code> — overrides <code>index.view</code> grants.',
    'settings.users_search_note' => 'The member Index search (<code>?action=search</code>).',
    'settings.users_search_whitelist' => 'Whitelist in search results',
    'settings.users_search_whitelist_hint' => 'Whether registered (whitelisted) torrents can appear in the member search.',
    'settings.users_search_whitelist_no' => 'Never shown',
    'settings.users_search_whitelist_yes' => 'Included (needs whitelist.view)',
    'settings.users_terms' => 'Registration terms',
    'settings.users_terms_hint' => '(empty = the checkbox links to <code>?action=tos</code>)',
    'settings.users_terms_note' => 'Registration always requires ticking the “I accept the terms” box; this only controls what the link shows.',
    'settings.users_terms_ph' => 'Plain text shown in a modal when the user clicks the terms link on the registration form.',
    'settings.users_title' => 'User Accounts',
    'settings.whitelist_daily_cap' => 'New hashes / day (global cap)',
    'settings.whitelist_disabled' => 'Disabled',
    'settings.whitelist_enabled' => 'Enabled',
    'settings.whitelist_intro_black' => '<strong>Blacklist</strong> = OpenTracker built with <code>-DWANT_ACCESSLIST_BLACK</code>: everything is served except blocked hashes.',
    'settings.whitelist_intro_match' => 'The mode must match the compiled binary and its <code>access.whitelist</code> / <code>access.blacklist</code> config line.',
