    'settings.whitelist_mode_sched_warn' => '<strong>Scheduled mode is ON</strong> — the janitor re-applies the schedule\'s mode within a minute, so a manually saved mode is reverted. To switch manually, disable Scheduled Tracker Mode below first (and remember the setting alone does not swap the OpenTracker binary — the schedule / <code>tracker-mode.sh</code> does that).',
