    'settings.wlupkeep_dead_after' => 'Call a torrent dead after (days)',
    'settings.wlupkeep_dead_after_hint' => '0 = off. Counted from the last scrape that showed <strong>no seeders and no leechers</strong>. A row that has never been scraped is <em>never</em> counted — no data is not the same as no peers, and the difference matters most when the scrape path is broken, which is exactly when a delete-on-zero rule would empty the list.',
    'settings.wlupkeep_dead_delete' => 'Delete them',
