    'settings.wlupkeep_dead_mark' => 'Mark them — nothing is removed',
    'settings.wlupkeep_dead_none' => 'Nothing',
    'settings.wlupkeep_intro' => 'A whitelist accumulates. Somebody registers a torrent, seeds it for a week and moves on, and years later the tracker is still serving a swarm with nobody in it. Both jobs below run from the <strong>janitor</strong>, never from a page view, and both are <strong>off by default</strong>.',
