    'title.whitelist' => 'Whitelist',
    'tos.acc1' => 'Creating an account is free and optional — the tracker itself works without one. An account only unlocks member features (such as the catalogue search) according to the groups granted to it.',
    'tos.acc2' => 'For an account we store: the username, the password (as a salted hash — never in plain text), the email address:email, the IP addresses used at registration and sign-in (abuse prevention), group memberships with their expiry dates, and in-app notifications.',
    'tos.acc2_opt' => ' (optional)',
    'tos.acc2_req' => ' (required and confirmed by a verification link)',
    'tos.acc3' => 'Emails are used solely for account operation: verification links, password resets, email-change confirmations and expiry/security notices. Account notices can be disabled on the account page; we never share addresses with third parties.',
    'tos.acc4' => 'Changing the account email requires confirmation from the current address and then from the new one; a cool-down period applies between changes. This protects accounts from hijacking.',
    'tos.acc5' => 'Session cookies (and the optional "stay signed in" token) are strictly functional. The sign-in duration is chosen at login; tokens are stored only as hashes and are invalidated by a password change or sign-out.',
    'tos.acc6' => 'Accounts used for abuse (spam, attacks on the service, deliberately registering infringing content after warnings) may be suspended or deleted, together with their whitelist registrations.',
    'tos.acc7' => 'To have your account and its data removed, contact the site email from your account address (or use the report form). Read notifications are pruned automatically after 90 days.',
    'tos.acc8' => 'Searching the index is a member feature. Search terms are not stored beyond the request; the results reflect what the tracker has observed, not what we host — we host nothing.',
    'tos.acc_head' => 'User accounts',
    'tos.h1' => 'Terms of Service',
    'tos.intro' => 'By using this tracker, you agree to the following terms:',
    'tos.lang1' => 'Choosing a language with the switcher sets a cookie named <code>lang</code> for the browser session only; it holds a two-letter code and nothing else. A signed-in account may save a language preference, which is kept with the account.',
    'tos.lang_head' => 'Languages and cookies',
    'tos.r1' => 'The service is free for personal use. Commercial organizations require written permission.',
    'tos.r2' => 'User tracking, DoS/DDoS attacks, and any attempts to disrupt the service are prohibited.',
    'tos.r3' => 'We do not guarantee service uptime. Availability may be limited without prior notice.',
    'tos.r4' => 'The user bears full responsibility for the legality of shared content in their jurisdiction.',
    'tos.r5' => 'Commercial use policy violations are subject to a fee of EUR 5,000.',
    'tos.r6' => 'We reserve the right to publish information about policy violations.',
    'tos.r7' => 'We respect user privacy. We do not store personal data beyond what is necessary for tracker operation.',
    'tos.r8' => 'Terms may change. Continued use of the service constitutes acceptance of changes.',
    'tos.r9' => '<strong>Connecting to the tracker constitutes acceptance of these terms.</strong>',
    'tos.r_index' => 'The tracker keeps an <strong>index</strong> of info hashes it has observed, with the torrent name and file list fetched from the swarm, so that reports can be matched to content. No files are downloaded or stored; entries expire when a swarm goes quiet.',
    'tos.r_wl' => 'Whitelist registrations are free and anonymous; the registrant\'s IP address is stored to detect abuse. Registered info hashes may be removed or banned at any time, and abusive registrants may be banned.',
